{
  "name": "GeminiChat Pro",
  "description": "A high-performance, real-time chat application with glassmorphism UI, Firebase backend, and Gemini AI integration for smart features.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export interface User {
  uid: string;
  name: string;
  email: string;
  photoURL: string;
  status: 'online' | 'offline';
  lastSeen: number;
  bio?: string;
  blockedUsers?: string[];
  chatLockPassword?: string; // Secret key to reveal locked chats
}

export type MessageType = 'text' | 'image' | 'file' | 'voice' | 'story_reply';
export type MessageStatus = 'sent' | 'delivered' | 'seen';

export interface Message {
  id: string;
  senderId: string;
  recipientId: string; // User ID or Group ID
  text: string;
  type: MessageType;
  timestamp: number;
  status: MessageStatus;
  fileUrl?: string;
  fileName?: string;
  isForwarded?: boolean;
  replyContext?: {
    messageId: string;
    text: string;
    senderName: string;
  };
  storyContext?: {
    storyId: string;
    mediaUrl: string;
    mediaType: 'image' | 'video';
  };
}

export interface Story {
  id: string;
  userId: string;
  userName: string;
  userPhoto: string;
  mediaUrl: string;
  mediaType: 'image' | 'video';
  caption?: string;
  timestamp: number;
  likes?: string[]; 
}

export interface Chat {
  id: string;
  type: 'private' | 'group';
  participants: string[];
  name?: string; // For groups
  groupIcon?: string; // For groups
  adminIds?: string[]; // For groups
  lastMessage?: {
    text: string;
    senderId: string;
    timestamp: number;
  };
  updatedAt: number;
  typing?: { [uid: string]: boolean };
  lockedBy?: string[]; // Array of UIDs who have locked this chat locally
}

export interface AuthState {
  user: User | null;
  loading: boolean;
  error: string | null;
}

export type CallType = 'voice' | 'video';
export interface CallSession {
  type: CallType;
  partner: User;
  isIncoming: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { User, CallType } from '../../types';

interface CallModalProps {
  type: CallType;
  partner: User;
  onHangUp: () => void;
}

export const CallModal: React.FC<CallModalProps> = ({ type, partner, onHangUp }) => {
  const [status, setStatus] = useState<'calling' | 'connected' | 'ended'>('calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(type === 'voice');
  const [duration, setDuration] = useState(0);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    // Start Call Logic
    const startMedia = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: type === 'video',
          audio: true
        });
        streamRef.current = stream;
        if (localVideoRef.current) {
          localVideoRef.current.srcObject = stream;
        }

        // Simulate connection delay
        setTimeout(() => setStatus('connected'), 2500);
      } catch (err) {
        console.error("Media Error:", err);
        alert("Could not access camera/microphone. Check permissions.");
        onHangUp();
      }
    };

    startMedia();

    return () => {
      streamRef.current?.getTracks().forEach(track => track.stop());
    };
  }, [type, onHangUp]);

  useEffect(() => {
    let interval: any;
    if (status === 'connected') {
      interval = setInterval(() => setDuration(d => d + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatDuration = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const toggleMute = () => {
    if (streamRef.current) {
      const audioTrack = streamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsMuted(!audioTrack.enabled);
      }
    }
  };

  const toggleVideo = () => {
    if (type === 'voice') return;
    if (streamRef.current) {
      const videoTrack = streamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setIsVideoOff(!videoTrack.enabled);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white overflow-hidden">
      {/* Background Partner Blur */}
      <div className="absolute inset-0 opacity-30 blur-3xl pointer-events-none">
        <img src={partner.photoURL} className="w-full h-full object-cover" alt="" />
      </div>

      {/* Main Content */}
      <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-6 h-full py-12">
        <div className="flex-1 flex flex-col items-center justify-center gap-6">
          <div className="relative">
            <div className={`w-32 h-32 md:w-48 md:h-48 rounded-full overflow-hidden border-4 border-white/20 shadow-2xl transition-all duration-700 ${status === 'calling' ? 'scale-110 animate-pulse' : 'scale-100'}`}>
              <img src={partner.photoURL} className="w-full h-full object-cover" alt="" />
            </div>
            {status === 'calling' && (
              <div className="absolute inset-0 rounded-full border-4 border-indigo-500 animate-ping opacity-50"></div>
            )}
          </div>

          <div className="text-center">
            <h2 className="text-3xl font-bold mb-2">{partner.name}</h2>
            <p className="text-indigo-400 font-bold tracking-widest uppercase text-xs">
              {status === 'calling' ? 'Calling...' : status === 'connected' ? `In ${type} call • ${formatDuration(duration)}` : 'Ending...'}
            </p>
          </div>
        </div>

        {/* Video Streams */}
        {type === 'video' && (
          <div className="absolute top-10 right-10 w-32 h-48 bg-black rounded-2xl overflow-hidden shadow-2xl border border-white/20 z-50 transition-all hover:scale-105">
            <video 
              ref={localVideoRef} 
              autoPlay 
              muted 
              playsInline 
              className={`w-full h-full object-cover scale-x-[-1] ${isVideoOff ? 'opacity-0' : 'opacity-100'}`}
            />
            {isVideoOff && (
              <div className="absolute inset-0 flex items-center justify-center bg-slate-900">
                <svg className="w-8 h-8 text-white/20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              </div>
            )}
          </div>
        )}

        {/* Controls */}
        <div className="flex items-center gap-6 pb-12">
          <button 
            onClick={toggleMute}
            className={`p-5 rounded-full backdrop-blur-md transition-all active:scale-90 ${isMuted ? 'bg-red-500/80 text-white' : 'bg-white/10 hover:bg-white/20 text-white'}`}
          >
            {isMuted ? (
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3zM5.5 5.5l13 13" /></svg>
            ) : (
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            )}
          </button>

          <button 
            onClick={onHangUp}
            className="p-7 bg-red-600 hover:bg-red-700 text-white rounded-full shadow-2xl shadow-red-600/40 transition-all active:scale-90"
          >
            <svg className="w-8 h-8 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24">
              <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" />
            </svg>
          </button>

          {type === 'video' && (
            <button 
              onClick={toggleVideo}
              className={`p-5 rounded-full backdrop-blur-md transition-all active:scale-90 ${isVideoOff ? 'bg-red-500/80 text-white' : 'bg-white/10 hover:bg-white/20 text-white'}`}
            >
              {isVideoOff ? (
                <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2zM3 3l18 18" /></svg>
              ) : (
                <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              )}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User, Chat, Story, CallSession } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showProfile, setShowProfile] = useState(false);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);

  const startCall = (user: User, type: 'voice' | 'video') => {
    setActiveCall({ partner: user, type, isIncoming: false });
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden">
      {/* Sidebar */}
      <div className={`${selectedChat ? 'hidden lg:flex' : 'flex'} w-full lg:w-96 h-full shrink-0 border-r border-slate-200 dark:border-slate-800`}>
        <Sidebar 
          currentUser={currentUser} 
          onChatSelect={setSelectedChat} 
          onProfileClick={() => setShowProfile(true)}
          activeChatId={selectedChat?.id}
          onStoryUpload={() => setShowStoryUpload(true)}
          onStoryView={setViewingStories}
          onUserClick={setViewingUser}
        />
      </div>

      {/* Main Chat Area */}
      <div className={`${!selectedChat ? 'hidden lg:flex' : 'flex'} flex-1 h-full relative overflow-hidden bg-slate-50/50 dark:bg-slate-900/20`}>
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
          />
        ) : (
          <div className="hidden lg:flex flex-1 flex-col items-center justify-center p-8 text-center h-full">
            <div className="w-24 h-24 bg-indigo-500/10 rounded-full flex items-center justify-center mb-6 animate-bounce-slow">
              <svg className="w-12 h-12 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
              </svg>
            </div>
            <h2 className="text-2xl font-bold mb-2">Select a Conversation</h2>
            <p className="text-slate-500 dark:text-slate-400 max-w-xs">
              Pick an existing chat from the left sidebar or search for a new contact to start messaging.
            </p>
          </div>
        )}
      </div>

      {/* Overlays */}
      {showProfile && (
        <ProfilePanel 
          user={currentUser} 
          onClose={() => setShowProfile(false)} 
          toggleDarkMode={toggleDarkMode}
          isDarkMode={isDarkMode}
        />
      )}

      {showStoryUpload && (
        <StoryUpload 
          currentUser={currentUser} 
          onClose={() => setShowStoryUpload(false)} 
        />
      )}

      {viewingStories && (
        <StoryViewer 
          stories={viewingStories} 
          currentUser={currentUser}
          onClose={() => setViewingStories(null)} 
        />
      )}

      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall}
        />
      )}

      {activeCall && (
        <CallModal 
          type={activeCall.type} 
          partner={activeCall.partner} 
          onHangUp={() => setActiveCall(null)} 
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup ? chat.participants.find(p => p !== currentUser.uid) || '' : chat.id;

  useEffect(() => {
    const sync = async () => {
      if (!isGroup && !otherUser) {
        const u = await getUserById(otherId);
        if (u) setOtherUser(u);
      }
      const msgs = await getMessages(chat.id);
      setMessages(prev => (prev.length !== msgs.length ? msgs : prev));
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id, otherId, isGroup]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;
    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: isGroup ? chat.id : otherId,
      text, type: 'text', timestamp: Date.now(), status: 'sent'
    };
    setMessages(prev => [...prev, msg]);
    setInputText('');
    await addMessage(msg);

    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      try {
        const res = await getAIResponse(text.replace('/ai', '').trim());
        const aiMsg: Message = {
          id: 'ai_' + Date.now(),
          senderId: 'gemini_ai',
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', timestamp: Date.now(), status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) {
        console.error("AI Error:", err);
      } finally {
        setIsTyping(false);
      }
    }
  };

  const handleToggleLock = async () => {
    if (!currentUser.chatLockPassword) {
      alert("Please set a Chat Lock Password in Settings first!");
      return;
    }
    await toggleChatLock(chat.id, currentUser.uid);
    setIsLocked(!isLocked);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 animate-in fade-in duration-300">
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
          </button>

          <div className="relative cursor-pointer" onClick={() => !isGroup && otherUser && onUserClick(otherUser)}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" alt="Profile" />
            {!isGroup && otherUser?.status === 'online' && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>}
          </div>

          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none flex items-center gap-2 truncate">
              {isGroup ? chat.name : otherUser?.name}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            <span className="text-[10px] text-slate-500 font-medium">{isGroup ? `${chat.participants.length} members` : (otherUser?.status === 'online' ? 'Online' : 'Offline')}</span>
          </div>
        </div>

        <div className="flex items-center gap-1">
          {!isGroup && otherUser && onCallStart && (
            <>
              <button onClick={() => onCallStart(otherUser, 'voice')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
              </button>
              <button onClick={() => onCallStart(otherUser, 'video')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              </button>
            </>
          )}
          <button onClick={handleToggleLock} className={`p-2.5 rounded-xl transition-all ${isLocked ? 'bg-indigo-500 text-white' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </button>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 scroll-smooth">
        {messages.length === 0 && !isTyping && (
          <div className="h-full flex flex-col items-center justify-center opacity-40 text-center p-8">
            <div className="w-16 h-16 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
            </div>
            <p className="text-sm font-medium">No messages yet. Say hi!</p>
          </div>
        )}
        {messages.map((msg, index) => (
          <MessageBubble key={msg.id || index} message={msg} isOwn={msg.senderId === currentUser.uid} isAI={msg.senderId === 'gemini_ai'} onReply={() => {}} onForward={() => {}} />
        ))}
        {isTyping && (
          <div className="flex items-center gap-2 ml-2 animate-in fade-in slide-in-from-left-2">
            <div className="flex gap-1">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></div>
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-3 md:p-4 glass border-t border-slate-200 dark:border-slate-800 flex gap-2 md:gap-3">
        <input type="text" value={inputText} onChange={e => setInputText(e.target.value)} placeholder="Type a message..." className="flex-1 bg-slate-100 dark:bg-slate-800/50 rounded-2xl px-5 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all border border-transparent" />
        <button type="submit" disabled={!inputText.trim()} className="p-3 bg-indigo-500 text-white rounded-2xl hover:bg-indigo-600 disabled:opacity-40 active:scale-90 transition-all shadow-lg shrink-0">
          <svg className="w-5 h-5 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
        </button>
      </form>
    </div>
