import React, { useState, useRef } from 'react';
import { User } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile } from '../../firebase';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode }) => {
  const { logout } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || 'Available');
  const [lockPass, setLockPass] = useState(user.chatLockPassword || '');
  const [newPhoto, setNewPhoto] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const size = 300; // Profile pics don't need to be huge
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, size, size);
        const compressed = canvas.toDataURL('image/jpeg', 0.7);
        setNewPhoto(compressed);
      };
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name: name.trim(),
        bio: bio.trim(),
        chatLockPassword: lockPass.trim(),
        photoURL: newPhoto || user.photoURL
      });
      setIsEditing(false);
    } catch (err) {
      alert("Error saving profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-sm h-full bg-white dark:bg-slate-900 shadow-2xl flex flex-col animate-slide-left">
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
          <h2 className="text-xl font-bold">Settings</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-8">
          <div className="flex flex-col items-center text-center">
            <div className="relative group cursor-pointer mb-4" onClick={() => isEditing && fileInputRef.current?.click()}>
              <img src={newPhoto || user.photoURL} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl transition-all group-hover:brightness-75" alt="" />
              {isEditing && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <svg className="w-8 h-8 text-white opacity-80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </div>
              )}
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoSelect} />
            </div>

            {isEditing ? (
              <div className="w-full space-y-4">
                <input 
                  type="text" value={name} onChange={e => setName(e.target.value)}
                  className="w-full bg-slate-100 dark:bg-slate-800 rounded-xl px-4 py-2 text-center font-bold outline-none ring-2 ring-indigo-500/20"
                />
                <textarea 
                  value={bio} onChange={e => setBio(e.target.value)}
                  className="w-full bg-slate-100 dark:bg-slate-800 rounded-xl px-4 py-2 text-center text-sm outline-none resize-none"
                  rows={2}
                />
                <div className="pt-2">
                   <label className="text-[10px] font-bold uppercase text-indigo-500 block mb-1">Chat Lock Password</label>
                   <input 
                    type="password" value={lockPass} onChange={e => setLockPass(e.target.value)}
                    className="w-full bg-slate-100 dark:bg-slate-800 rounded-xl px-4 py-2 text-center text-sm font-mono"
                  />
                </div>
                <div className="flex gap-2 pt-2">
                  <button onClick={() => { setIsEditing(false); setNewPhoto(null); }} className="flex-1 py-3 bg-slate-100 dark:bg-slate-800 rounded-xl text-sm font-bold">Cancel</button>
                  <button onClick={handleSave} className="flex-1 py-3 bg-indigo-500 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-500/20">{isSaving ? 'Saving...' : 'Save'}</button>
                </div>
              </div>
            ) : (
              <div>
                <h3 className="text-lg font-bold">{user.name}</h3>
                <p className="text-sm text-slate-500 mt-1 max-w-[200px] mx-auto leading-relaxed">{user.bio || 'No bio yet'}</p>
                <button onClick={() => setIsEditing(true)} className="mt-5 text-xs font-bold bg-indigo-500/10 text-indigo-500 px-6 py-2.5 rounded-full hover:bg-indigo-500 hover:text-white transition-all">Edit Profile</button>
              </div>
            )}
          </div>

          <div className="space-y-4 pt-4">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Settings</h4>
            <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl cursor-pointer" onClick={toggleDarkMode}>
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-500/10 text-indigo-500 rounded-lg">
                  {isDarkMode ? <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg> : <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>}
                </div>
                <span className="text-sm font-semibold">Dark Mode</span>
              </div>
              <div className={`w-10 h-5 rounded-full transition-colors relative ${isDarkMode ? 'bg-indigo-500' : 'bg-slate-300'}`}>
                <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-all ${isDarkMode ? 'left-5.5' : 'left-0.5'}`}></div>
              </div>
            </div>
            <button onClick={logout} className="w-full p-4 bg-red-50 dark:bg-red-900/10 text-red-500 rounded-2xl text-sm font-bold text-left flex items-center gap-3">
              <div className="p-2 bg-red-500/10 rounded-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </div>
              Sign Out
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * MOCK FIREBASE IMPLEMENTATION
 */

const STORAGE_KEY_USERS = 'gemini_chat_db_users';
const STORAGE_KEY_SESSION = 'chat_session';
const STORAGE_KEY_STORIES = 'gemini_chat_db_stories';
const STORAGE_KEY_MESSAGES = 'gemini_chat_db_messages';
const STORAGE_KEY_CHATS = 'gemini_chat_db_chats';

const getLocal = (key: string) => {
  try {
    return JSON.parse(localStorage.getItem(key) || '[]');
  } catch (e) {
    return [];
  }
};

const saveLocal = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {
    if (e instanceof DOMException && (e.code === 22 || e.code === 1014 || e.name === 'QuotaExceededError')) {
      const messages = getLocal(STORAGE_KEY_MESSAGES);
      localStorage.setItem(STORAGE_KEY_MESSAGES, JSON.stringify(messages.slice(-20)));
      localStorage.setItem(key, JSON.stringify(data));
    } else {
      throw e;
    }
  }
};

