import { useState, useEffect } from 'react';
import { 
  auth, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup, 
  signOut, 
  updateProfile,
} from '../firebase';
import { User } from '../types';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Listen to mock auth state changes
    const unsubscribe = auth.onAuthStateChanged((mockUser: any) => {
      if (mockUser) {
        // Direct conversion of mockUser to our User type
        const finalUser: User = {
          uid: mockUser.uid,
          name: mockUser.name || mockUser.displayName || 'Anonymous',
          email: mockUser.email || '',
          photoURL: mockUser.photoURL || `https://picsum.photos/seed/${mockUser.uid}/200`,
          status: mockUser.status || 'online',
          lastSeen: mockUser.lastSeen || Date.now(),
          bio: mockUser.bio,
          blockedUsers: mockUser.blockedUsers || [],
          chatLockPassword: mockUser.chatLockPassword
        };
        setUser(finalUser);
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const signup = async (email: string, pass: string, name: string) => {
    const res = await createUserWithEmailAndPassword(auth, email, pass);
    const updated = await updateProfile(res.user, { 
      displayName: name,
      name: name,
      photoURL: `https://picsum.photos/seed/${res.user.uid}/200`
    });
    return updated;
  };

  const login = async (email: string, pass: string) => {
    const res = await signInWithEmailAndPassword(auth, email, pass);
    return res.user;
  };

  const googleSignIn = async () => {
    const res = await signInWithPopup();
    return res.user;
  };

  const logout = async () => {
    await signOut();
  };

  return { user, loading, signup, login, googleSignIn, logout };
};

import React, { useState, useEffect, useRef } from 'react';
import { User, CallType } from '../../types';

interface CallModalProps {
  type: CallType;
  partner: User;
  onHangUp: () => void;
}

export const CallModal: React.FC<CallModalProps> = ({ type, partner, onHangUp }) => {
  const [status, setStatus] = useState<'calling' | 'connected' | 'ended' | 'denied'>('calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(type === 'voice');
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startMedia = async () => {
    setError(null);
    setStatus('calling');

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("Your browser does not support calling features.");
      setStatus('denied');
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: type === 'video' ? { facingMode: 'user' } : false,
        audio: true
      });

      streamRef.current = stream;
      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }

      // Simulate connection delay
      setTimeout(() => setStatus('connected'), 2000);
    } catch (err: any) {
      console.error("Media Error:", err);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        setError("Camera/Microphone access was denied. Please check your browser site settings and try again.");
      } else {
        setError(`Could not start call: ${err.message || 'Unknown error'}`);
      }
      setStatus('denied');
    }
  };

  useEffect(() => {
    startMedia();
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [type]);

  useEffect(() => {
    let interval: any;
    if (status === 'connected') {
      interval = setInterval(() => setDuration(d => d + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatDuration = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const toggleMute = () => {
    if (streamRef.current) {
      const audioTrack = streamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsMuted(!audioTrack.enabled);
      }
    }
  };

  const toggleVideo = () => {
    if (type === 'voice') return;
    if (streamRef.current) {
      const videoTrack = streamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setIsVideoOff(!videoTrack.enabled);
      }
    }
  };

  if (status === 'denied') {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white p-6 text-center">
        <div className="w-20 h-20 bg-red-500/20 rounded-full flex items-center justify-center mb-6 border border-red-500/50">
          <svg className="w-10 h-10 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        </div>
        <h2 className="text-2xl font-bold mb-4">Permission Denied</h2>
        <p className="text-slate-400 mb-8 max-w-sm">{error}</p>
        <div className="flex gap-4">
          <button onClick={onHangUp} className="px-6 py-3 bg-white/10 rounded-xl font-bold hover:bg-white/20 transition-all">Go Back</button>
          <button onClick={startMedia} className="px-6 py-3 bg-indigo-500 rounded-xl font-bold hover:bg-indigo-600 transition-all">Try Again</button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-500">
      {/* Background Partner Blur */}
      <div className="absolute inset-0 opacity-30 blur-3xl pointer-events-none">
        <img src={partner.photoURL} className="w-full h-full object-cover" alt="" />
      </div>

      {/* Main Content */}
      <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-6 h-full py-12">
        <div className="flex-1 flex flex-col items-center justify-center gap-6">
          <div className="relative">
            <div className={`w-32 h-32 md:w-48 md:h-48 rounded-[2.5rem] overflow-hidden border-4 border-white/20 shadow-2xl transition-all duration-700 ${status === 'calling' ? 'scale-110 animate-pulse' : 'scale-100'}`}>
              <img src={partner.photoURL} className="w-full h-full object-cover" alt="" />
            </div>
            {status === 'calling' && (
              <div className="absolute inset-0 rounded-[2.5rem] border-4 border-indigo-500 animate-ping opacity-50"></div>
            )}
          </div>

          <div className="text-center">
            <h2 className="text-3xl font-bold mb-2 tracking-tight">{partner.name}</h2>
            <p className="text-indigo-400 font-bold tracking-widest uppercase text-xs">
              {status === 'calling' ? 'Calling...' : status === 'connected' ? `In ${type} call • ${formatDuration(duration)}` : 'Ending...'}
            </p>
          </div>
        </div>

        {/* Local Video Preview */}
        {type === 'video' && (
          <div className="absolute top-10 right-10 w-32 h-48 bg-slate-900 rounded-2xl overflow-hidden shadow-2xl border border-white/20 z-50 transition-all hover:scale-105 group">
            <video 
              ref={localVideoRef} 
              autoPlay 
              muted 
              playsInline 
              className={`w-full h-full object-cover scale-x-[-1] transition-opacity duration-500 ${isVideoOff ? 'opacity-0' : 'opacity-100'}`}
            />
            {isVideoOff && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 gap-2">
                <svg className="w-8 h-8 text-white/20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                <span className="text-[10px] text-white/30 font-bold uppercase tracking-tighter">Camera Off</span>
              </div>
            )}
          </div>
        )}

        {/* Controls */}
        <div className="flex items-center gap-6 pb-12 animate-in slide-in-from-bottom-4 duration-700">
          <button 
            onClick={toggleMute}
            className={`p-5 rounded-full backdrop-blur-md transition-all active:scale-90 ${isMuted ? 'bg-red-500 text-white shadow-lg shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}
          >
            {isMuted ? (
              <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3zM5.5 5.5l13 13" /></svg>
