              </div>
              <div className="flex-1 min-w-0 flex flex-col justify-center">
                <span className={`text-[10px] font-bold uppercase tracking-wider ${isOwn ? 'text-indigo-200' : 'text-indigo-500'}`}>Story Reply</span>
                <p className={`text-[11px] truncate italic ${isOwn ? 'text-white/60' : 'text-slate-500'}`}>View original story</p>
              </div>
            </div>
          )}

          {/* Integrated Image Preview */}
          {message.type === 'image' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-xl">
              <img src={message.fileUrl} alt="Sent" className="w-full max-h-80 object-cover" />
              <div className="absolute bottom-2 right-2 px-2 py-0.5 bg-black/30 backdrop-blur-md rounded-full flex items-center gap-1.5 border border-white/10">
                <span className="text-[9px] font-bold text-white uppercase">{formatTime(message.timestamp)}</span>
                {renderStatus(true)}
              </div>
            </div>
          )}

          {/* Integrated Video Preview */}
          {message.type === 'video' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-xl bg-black">
              <video 
                ref={videoRef}
                src={message.fileUrl} 
                className="w-full max-h-80 object-contain cursor-pointer" 
                controls 
              />
              <div className="absolute top-2 right-2 p-1.5 bg-black/40 backdrop-blur-md rounded-full border border-white/10">
                <svg className="w-3.5 h-3.5 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M7 6.75V17.25C7 17.5908 7.15332 17.9092 7.4209 18.1143C7.68848 18.3193 8.03125 18.3809 8.35156 18.2822L16.6016 13.0322C16.8506 12.8721 17 12.5977 17 12.25C17 11.9023 16.8506 11.6279 16.6016 11.4678L8.35156 6.21777C8.03125 6.11914 7.68848 6.18066 7.4209 6.38574C7.15332 6.59082 7 6.90918 7 7.25" /></svg>
