  }

  const { password, ...userProfile } = user;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyAuthListeners(userProfile);
  return { user: userProfile };
};

export const signOut = async () => {
  if (auth.currentUser) {
    const users = getLocal(STORAGE_KEY_USERS);
    const i = users.findIndex((u: any) => u.uid === auth.currentUser.uid);
    if (i !== -1) {
      users[i].status = 'offline';
      users[i].lastSeen = Date.now();
      saveLocal(STORAGE_KEY_USERS, users);
    }
  }
  localStorage.removeItem(STORAGE_KEY_SESSION);
  notifyAuthListeners(null);
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const targetUid = user.uid || user.id;
  const idx = users.findIndex((u: any) => u.uid === targetUid);

  if (idx !== -1) {
    // Update the database
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);

    // Create session profile (no password)
    const updated = { ...users[idx] };
    delete updated.password;

    // Update local session storage
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updated));

    // Notify all active listeners in the app
    notifyAuthListeners(updated);

    return updated;
  }
  throw new Error("User not found");
};

// --- CHAT & MESSAGING ---

export const createGroup = async (name: string, participants: string[], adminId: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  const newGroup = {
    id: 'group_' + crypto.randomUUID(),
    type: 'group',
    name,
    participants: [...participants, adminId],
    adminIds: [adminId],
    updatedAt: Date.now(),
    lockedBy: []
  };
  chats.push(newGroup);
  saveLocal(STORAGE_KEY_CHATS, chats);
  return newGroup;
};

export const toggleChatLock = async (chatId: string, userId: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  const chatIdx = chats.findIndex((c: any) => c.id === chatId);
  if (chatIdx !== -1) {
    const lockedBy = chats[chatIdx].lockedBy || [];
    const idx = lockedBy.indexOf(userId);
    if (idx === -1) lockedBy.push(userId);
    else lockedBy.splice(idx, 1);
    chats[chatIdx].lockedBy = lockedBy;
    saveLocal(STORAGE_KEY_CHATS, chats);
  }
};

export const addMessage = async (msg: any) => {
  const messages = getLocal(STORAGE_KEY_MESSAGES);
  messages.push(msg);
  saveLocal(STORAGE_KEY_MESSAGES, messages.slice(-500));

  const chats = getLocal(STORAGE_KEY_CHATS);
  const chatId = msg.recipientId.startsWith('group_') 
    ? msg.recipientId 
    : [msg.senderId, msg.recipientId].sort().join('_');

  const chatIdx = chats.findIndex((c: any) => c.id === chatId);
  const update = {
    lastMessage: { text: msg.text, senderId: msg.senderId, timestamp: msg.timestamp },
    updatedAt: msg.timestamp
  };

  if (chatIdx !== -1) {
    chats[chatIdx] = { ...chats[chatIdx], ...update };
  } else {
    chats.push({
      id: chatId, type: 'private', 
      participants: [msg.senderId, msg.recipientId], 
      ...update, lockedBy: []
    });
  }
  saveLocal(STORAGE_KEY_CHATS, chats);
};

export const getMessages = async (chatId: string) => {
  const all = getLocal(STORAGE_KEY_MESSAGES);
  if (chatId.startsWith('group_')) {
    return all.filter((m: any) => m.recipientId === chatId);
  }
  const [u1, u2] = chatId.split('_');
  return all.filter((m: any) => 
    (m.senderId === u1 && m.recipientId === u2) || (m.senderId === u2 && m.recipientId === u1)
  );
};

export const getMyChats = async (uid: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  return chats.filter((c: any) => c.participants.includes(uid))
              .sort((a: any, b: any) => b.updatedAt - a.updatedAt);
};

export const getAllUsers = async () => getLocal(STORAGE_KEY_USERS);
export const getUserById = async (uid: string) => getLocal(STORAGE_KEY_USERS).find((u: any) => u.uid === uid);

// --- CALLS ---

export const initiateCall = async (callerId: string, receiverId: string, type: 'voice' | 'video') => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const callId = 'call_' + crypto.randomUUID();
  const newCall = {
    id: callId,
    callerId,
    receiverId,
    type,
    status: 'ringing',
    timestamp: Date.now()
  };
  calls.push(newCall);
  saveLocal(STORAGE_KEY_CALLS, calls);
  return newCall;
};

export const getIncomingCall = async (userId: string) => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  // A call is valid if it's addressed to the user and started in the last 60 seconds
  return calls.find((c: any) => c.receiverId === userId && c.status === 'ringing' && (Date.now() - c.timestamp) < 60000);
};

export const updateCallStatus = async (callId: string, status: 'accepted' | 'rejected' | 'ended') => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const idx = calls.findIndex((c: any) => c.id === callId);
  if (idx !== -1) {
    calls[idx].status = status;
    saveLocal(STORAGE_KEY_CALLS, calls);
    return calls[idx];
  }
  return null;
};

export const getCallById = async (callId: string) => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  return calls.find((c: any) => c.id === callId);
};

export const cleanOldCalls = () => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const filtered = calls.filter((c: any) => (Date.now() - c.timestamp) < 300000); // Keep only 5 mins
  if (filtered.length !== calls.length) {
    saveLocal(STORAGE_KEY_CALLS, filtered);
  }
};

// --- STORIES ---
export const addStory = async (story: any) => {
  const s = getLocal(STORAGE_KEY_STORIES);
  s.push({ ...story, likes: [] });
  saveLocal(STORAGE_KEY_STORIES, s.slice(-50));
};
export const getStories = async () => getLocal(STORAGE_KEY_STORIES).filter((s: any) => (Date.now() - s.timestamp) < 86400000);
export const likeStory = async (id: string, uid: string) => {
  const s = getLocal(STORAGE_KEY_STORIES);
  const i = s.findIndex((st: any) => st.id === id);
  if (i !== -1) {
    s[i].likes = s[i].likes || [];
    const li = s[i].likes.indexOf(uid);
    if (li === -1) s[i].likes.push(uid); else s[i].likes.splice(li, 1);
    saveLocal(STORAGE_KEY_STORIES, s);
  }
};
export const sendStoryReply = async (rid: string, sid: string, text: string, story: any) => {
  const msg = {
    id: 'm_' + Math.random().toString(36).substr(2, 9),
    senderId: sid, recipientId: rid, text, type: 'story_reply', 
    timestamp: Date.now(), status: 'sent',
    storyContext: { storyId: story.id, mediaUrl: story.mediaUrl, mediaType: story.mediaType }
  };
  await addMessage(msg);
  return msg;
};

// Utils
export const doc = (db: any, c: string, id: string) => ({ c, id });
export const getDoc = async (ref: any) => {
  const d = getLocal(STORAGE_KEY_USERS).find((u: any) => u.uid === ref.id);
  return { exists: () => !!d, data: () => d };
};
export const setDoc = async (ref: any, data: any, opt?: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const i = users.findIndex((u: any) => u.uid === ref.id);
  if (i !== -1) {
    users[i] = opt?.merge ? { ...users[i], ...data } : data;
    saveLocal(STORAGE_KEY_USERS, users);
  } else {
    users.push({ ...data, uid: ref.id });
    saveLocal(STORAGE_KEY_USERS, users);
  }
};
export const serverTimestamp = () => Date.now();
export const blockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = u[i].blockedUsers || [];
    if (!u[i].blockedUsers.includes(target)) u[i].blockedUsers.push(target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};
export const unblockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = (u[i].blockedUsers || []).filter((id: string) => id !== target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};

import React, { useState, useEffect } from 'react';
import { User, Chat, Story, CallSession } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showProfile, setShowProfile] = useState(false);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);

  // Poll for incoming calls
  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; // Don't interrupt existing call

      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id,
            partner: caller,
            type: incoming.type,
            callerId: incoming.callerId,
            receiverId: incoming.receiverId,
            status: incoming.status,
            isIncoming: true,
            timestamp: incoming.timestamp
          });
        }
      }
    };

    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id,
      partner: user, 
      type, 
      callerId: currentUser.uid,
      receiverId: user.uid,
      status: 'ringing',
      isIncoming: false,
      timestamp: call.timestamp
    });
  };

  const handleCallEnd = async () => {
    if (activeCall) {
      await updateCallStatus(activeCall.id, 'ended');
      setActiveCall(null);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden">
      {/* Sidebar */}
      <div className={`${selectedChat ? 'hidden lg:flex' : 'flex'} w-full lg:w-96 h-full shrink-0 border-r border-slate-200 dark:border-slate-800`}>
        <Sidebar 
          currentUser={currentUser} 
          onChatSelect={setSelectedChat} 
          onProfileClick={() => setShowProfile(true)}
          activeChatId={selectedChat?.id}
          onStoryUpload={() => setShowStoryUpload(true)}
          onStoryView={setViewingStories}
          onUserClick={setViewingUser}
        />
      </div>

      {/* Main Chat Area */}
      <div className={`${!selectedChat ? 'hidden lg:flex' : 'flex'} flex-1 h-full relative overflow-hidden bg-slate-50/50 dark:bg-slate-900/20`}>
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
          />
        ) : (
          <div className="hidden lg:flex flex-1 flex-col items-center justify-center p-8 text-center h-full">
            <div className="w-24 h-24 bg-indigo-500/10 rounded-full flex items-center justify-center mb-6 animate-bounce-slow">
              <svg className="w-12 h-12 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
              </svg>
            </div>
            <h2 className="text-2xl font-bold mb-2">Select a Conversation</h2>
            <p className="text-slate-500 dark:text-slate-400 max-w-xs">
              Pick an existing chat from the left sidebar or search for a new contact to start messaging.
            </p>
          </div>
        )}
      </div>

      {/* Overlays */}
      {showProfile && (
        <ProfilePanel 
          user={currentUser} 
          onClose={() => setShowProfile(false)} 
          toggleDarkMode={toggleDarkMode}
          isDarkMode={isDarkMode}
        />
      )}

      {showStoryUpload && (
        <StoryUpload 
          currentUser={currentUser} 
          onClose={() => setShowStoryUpload(false)} 
        />
      )}

      {viewingStories && (
        <StoryViewer 
          stories={viewingStories} 
          currentUser={currentUser}
          onClose={() => setViewingStories(null)} 
        />
      )}

      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall}
        />
      )}

      {activeCall && (
        <CallModal 
          session={activeCall}
          onHangUp={handleCallEnd} 
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, CallType, CallSession, CallStatus } from '../../types';
import { updateCallStatus, getCallById } from '../../firebase';

interface CallModalProps {
  session: CallSession;
  onHangUp: () => void;
}

export const CallModal: React.FC<CallModalProps> = ({ session, onHangUp }) => {
  const [status, setStatus] = useState<CallStatus | 'calling' | 'denied'>(session.isIncoming ? 'ringing' : 'calling');
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(session.type === 'voice');
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const isMounted = useRef(true);

  // Status Sync Polling
  useEffect(() => {
    if (status === 'ended' || status === 'rejected') {
        onHangUp();
        return;
    }

    const poll = async () => {
        const remoteCall = await getCallById(session.id);
        if (!remoteCall) {
            setStatus('ended');
            return;
        }
        if (remoteCall.status !== status) {
            setStatus(remoteCall.status);
            if (remoteCall.status === 'accepted' && !streamRef.current) {
                startMedia();
            }
        }
    };

    const itv = setInterval(poll, 2000);
    return () => clearInterval(itv);
  }, [status, session.id]);

  const startMedia = async () => {
    if (!isMounted.current) return;

    setError(null);

    await new Promise(resolve => setTimeout(resolve, 500));

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      if (isMounted.current) {
        setError("Your browser does not support calling features.");
        setStatus('denied');
      }
      return;
    }

    try {
      const constraints = {
        audio: true,
        video: session.type === 'video' ? {
          width: { ideal: 1280 },
          height: { ideal: 720 },
          facingMode: 'user'
        } : false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);

      if (!isMounted.current) {
        stream.getTracks().forEach(track => track.stop());
        return;
      }

      streamRef.current = stream;
      if (localVideoRef.current) {
        localVideoRef.current.srcObject = stream;
      }
    } catch (err: any) {
      console.error("Media Error:", err);
      if (isMounted.current) {
        setError(`Call error: ${err.message || 'Check permissions'}`);
        setStatus('denied');
      }
    }
  };

  const handleAccept = async () => {
    await updateCallStatus(session.id, 'accepted');
    setStatus('accepted');
    startMedia();
  };

  const handleDecline = async () => {
    await updateCallStatus(session.id, 'rejected');
    onHangUp();
  };

  useEffect(() => {
    isMounted.current = true;
    if (!session.isIncoming) {
        startMedia();
    }
    return () => {
      isMounted.current = false;
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [session.type, session.isIncoming]);

  useEffect(() => {
    let interval: any;
    if (status === 'accepted') {
      interval = setInterval(() => {
        if (isMounted.current) setDuration(d => d + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatDuration = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const toggleMute = () => {
    if (streamRef.current) {
      const audioTrack = streamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsMuted(!audioTrack.enabled);
      }
    }
  };

  const toggleVideo = () => {
    if (session.type === 'voice') return;
    if (streamRef.current) {
      const videoTrack = streamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setIsVideoOff(!videoTrack.enabled);
      }
    }
  };

  if (status === 'denied') {
    return (
      <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white p-8 text-center animate-in fade-in duration-300">
        <div className="w-24 h-24 bg-red-500/10 rounded-full flex items-center justify-center mb-8 border border-red-500/20 shadow-[0_0_50px_rgba(239,68,68,0.1)]">
          <svg className="w-12 h-12 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        </div>
        <h2 className="text-3xl font-bold mb-4">Connection Failed</h2>
        <p className="text-slate-400 mb-10 max-w-sm leading-relaxed">{error}</p>
        <button onClick={onHangUp} className="px-8 py-4 bg-white/5 border border-white/10 rounded-2xl font-bold hover:bg-white/10 transition-all active:scale-95">Go Back</button>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-500">
      {/* Background Partner Blur */}
      <div className="absolute inset-0 opacity-20 blur-[100px] pointer-events-none">
        <img src={session.partner.photoURL} className="w-full h-full object-cover scale-150" alt="" />
      </div>

      {/* Main Content */}
      <div className="relative z-10 flex flex-col items-center w-full max-w-lg px-6 h-full py-12">
        <div className="flex-1 flex flex-col items-center justify-center gap-8">
          <div className="relative">
            <div className={`w-36 h-36 md:w-56 md:h-56 rounded-[3.5rem] overflow-hidden border-4 border-white/10 shadow-2xl transition-all duration-1000 ${status === 'calling' || status === 'ringing' ? 'scale-105 animate-pulse' : 'scale-100'}`}>
              <img src={session.partner.photoURL} className="w-full h-full object-cover" alt="" />
            </div>
            {(status === 'calling' || status === 'ringing') && (
              <div className="absolute inset-0 rounded-[3.5rem] border-4 border-indigo-500 animate-ping opacity-30"></div>
            )}
            <div className={`absolute -bottom-4 left-1/2 -translate-x-1/2 px-4 py-1.5 rounded-full backdrop-blur-xl border border-white/10 text-[10px] font-black uppercase tracking-[0.2em] transition-all duration-500 ${status === 'accepted' ? 'bg-green-500/20 text-green-400' : 'bg-white/10 text-white/50'}`}>
              {status === 'accepted' ? 'Live Session' : session.isIncoming ? 'Incoming Call' : 'Outgoing Call'}
            </div>
          </div>

          <div className="text-center">
            <h2 className="text-4xl font-black mb-3 tracking-tight">{session.partner.name}</h2>
            <p className="text-indigo-400/80 font-bold tracking-[0.3em] uppercase text-[10px]">
              {status === 'calling' ? 'Calling...' : status === 'ringing' ? 'Ringing...' : status === 'accepted' ? `In Call • ${formatDuration(duration)}` : 'Connecting...'}
            </p>
          </div>
        </div>

        {/* Local Video Preview */}
        {session.type === 'video' && status === 'accepted' && (
          <div className="absolute top-10 right-10 w-36 h-52 bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl border border-white/10 z-50 transition-all hover:scale-105 group ring-1 ring-white/5">
            <video 
              ref={localVideoRef} 
              autoPlay 
              muted 
              playsInline 
              className={`w-full h-full object-cover scale-x-[-1] transition-opacity duration-700 ${isVideoOff ? 'opacity-0' : 'opacity-100'}`}
            />
            {isVideoOff && (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 gap-3">
                <div className="p-3 bg-white/5 rounded-full">
                  <svg className="w-8 h-8 text-white/20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                </div>
                <span className="text-[10px] text-white/20 font-black uppercase tracking-widest">Cam Off</span>
              </div>
            )}
          </div>
        )}

        {/* Controls */}
        <div className="flex items-center gap-8 pb-16 animate-in slide-in-from-bottom-8 duration-1000">
          {status === 'ringing' && session.isIncoming ? (
            <>
              <button 
                onClick={handleDecline}
                className="p-8 bg-red-600 hover:bg-red-500 text-white rounded-full shadow-2xl shadow-red-600/40 transition-all active:scale-95 flex items-center justify-center"
              >
                <svg className="w-10 h-10 rotate-[135deg]" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" />
                </svg>
              </button>
              <button 
                onClick={handleAccept}
                className="p-8 bg-green-500 hover:bg-green-400 text-white rounded-full shadow-2xl shadow-green-500/40 transition-all active:scale-95 flex items-center justify-center animate-bounce"
              >
                <svg className="w-10 h-10" fill="currentColor" viewBox="0 0 24 24">
