// Utils
export const blockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = u[i].blockedUsers || [];
    if (!u[i].blockedUsers.includes(target)) u[i].blockedUsers.push(target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};
export const unblockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = (u[i].blockedUsers || []).filter((id: string) => id !== target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};

import React, { useState, useEffect } from 'react';
import { AuthView } from './components/Auth/AuthView';
import { ChatDashboard } from './components/Chat/ChatDashboard';
import { AdminDashboard } from './components/Admin/AdminDashboard';
import { useAuth } from './hooks/useAuth';

const App: React.FC = () => {
  const { user, loading } = useAuth();
  const [isAdminView, setIsAdminView] = useState(false);
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // If user is super admin, default to admin view or offer switch
  useEffect(() => {
    if (user?.email === 'betterrroxx@gmail.com') {
      setIsAdminView(true);
    } else {
      setIsAdminView(false);
    }
  }, [user]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 animate-pulse font-medium">Initializing Secure Connection...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen overflow-hidden text-slate-900 dark:text-slate-100">
      {!user ? (
        <AuthView />
      ) : isAdminView ? (
        <AdminDashboard 
          currentUser={user} 
          onExit={() => setIsAdminView(false)}
        />
      ) : (
        <div className="relative h-full">
           {user.email === 'betterrroxx@gmail.com' && (
             <button 
              onClick={() => setIsAdminView(true)}
