      photoURL: `https://picsum.photos/seed/google/200`,
      name: 'Google Explorer',
      blockedUsers: [],
      lockedChats: [],
      chatLockPassword: ''
    };
    users.push(user);
    saveLocal(STORAGE_KEY_USERS, users);
  }

  const { password, ...userProfile } = user;
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(userProfile));
  notifyAuthListeners(userProfile);
  return { user: userProfile };
};

export const signOut = async () => {
  if (auth.currentUser) {
    const users = getLocal(STORAGE_KEY_USERS);
    const i = users.findIndex((u: any) => u.uid === auth.currentUser.uid);
    if (i !== -1) {
      users[i].status = 'offline';
      users[i].lastSeen = Date.now();
      saveLocal(STORAGE_KEY_USERS, users);
    }
  }
  localStorage.removeItem(STORAGE_KEY_SESSION);
  notifyAuthListeners(null);
};

export const updateProfile = async (user: any, updates: any) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const targetUid = user.uid || user.id;
  const idx = users.findIndex((u: any) => u.uid === targetUid);

  if (idx !== -1) {
    users[idx] = { ...users[idx], ...updates };
    saveLocal(STORAGE_KEY_USERS, users);
    const updated = { ...users[idx] };
    delete updated.password;
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updated));
    notifyAuthListeners(updated);
    return updated;
  }
  throw new Error("User not found");
};

// --- ADMIN FUNCTIONS ---

export const admin_getAllUsers = async () => getLocal(STORAGE_KEY_USERS);

export const admin_toggleGlobalBlock = async (uid: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const i = users.findIndex((u: any) => u.uid === uid);
  if (i !== -1) {
    if (users[i].isAdmin) return; // Cannot block other admins via basic panel
    users[i].isGloballyBlocked = !users[i].isGloballyBlocked;
    if (users[i].isGloballyBlocked) users[i].status = 'offline';
    saveLocal(STORAGE_KEY_USERS, users);
  }
};

export const admin_deleteUser = async (uid: string) => {
  const users = getLocal(STORAGE_KEY_USERS).filter((u: any) => u.uid !== uid || u.isAdmin);
  saveLocal(STORAGE_KEY_USERS, users);

  // Clean up messages and chats for this user too
  const messages = getLocal(STORAGE_KEY_MESSAGES).filter((m: any) => m.senderId !== uid && m.recipientId !== uid);
  saveLocal(STORAGE_KEY_MESSAGES, messages);

  const chats = getLocal(STORAGE_KEY_CHATS).filter((c: any) => !c.participants.includes(uid));
  saveLocal(STORAGE_KEY_CHATS, chats);
};

export const admin_getStats = async () => {
  return {
    users: getLocal(STORAGE_KEY_USERS).length,
    messages: getLocal(STORAGE_KEY_MESSAGES).length,
    chats: getLocal(STORAGE_KEY_CHATS).length,
    stories: getLocal(STORAGE_KEY_STORIES).length
  };
};

// --- MESSAGING ---

export const createGroup = async (name: string, participants: string[], adminId: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  const newGroup = {
    id: 'group_' + crypto.randomUUID(),
    type: 'group',
    name,
    participants: [...participants, adminId],
    adminIds: [adminId],
    updatedAt: Date.now(),
    lockedBy: []
  };
  chats.push(newGroup);
  saveLocal(STORAGE_KEY_CHATS, chats);
  return newGroup;
};

export const toggleChatLock = async (chatId: string, userId: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  const chatIdx = chats.findIndex((c: any) => c.id === chatId);
  if (chatIdx !== -1) {
    const lockedBy = chats[chatIdx].lockedBy || [];
    const idx = lockedBy.indexOf(userId);
    if (idx === -1) lockedBy.push(userId);
    else lockedBy.splice(idx, 1);
    chats[chatIdx].lockedBy = lockedBy;
    saveLocal(STORAGE_KEY_CHATS, chats);
  }
};

export const addMessage = async (msg: any) => {
  const messages = getLocal(STORAGE_KEY_MESSAGES);
  messages.push(msg);
  saveLocal(STORAGE_KEY_MESSAGES, messages.slice(-500));

  const chats = getLocal(STORAGE_KEY_CHATS);
  const chatId = msg.recipientId.startsWith('group_') 
    ? msg.recipientId 
    : [msg.senderId, msg.recipientId].sort().join('_');

  const chatIdx = chats.findIndex((c: any) => c.id === chatId);
  const update = {
    lastMessage: { text: msg.text, senderId: msg.senderId, timestamp: msg.timestamp },
    updatedAt: msg.timestamp
  };

  if (chatIdx !== -1) {
    chats[chatIdx] = { ...chats[chatIdx], ...update };
  } else {
    chats.push({
      id: chatId, type: 'private', 
      participants: [msg.senderId, msg.recipientId], 
      ...update, lockedBy: []
    });
  }
  saveLocal(STORAGE_KEY_CHATS, chats);
};

export const markMessagesAsDelivered = async (chatId: string, userId: string) => {
  const messages = getLocal(STORAGE_KEY_MESSAGES);
  let changed = false;
  messages.forEach((m: any) => {
    // If user is recipient and message is only 'sent', mark as 'delivered'
    if (m.recipientId === userId && m.status === 'sent') {
      m.status = 'delivered';
      changed = true;
    }
    // For groups, logic is simplified: anyone reading marks it as delivered if it was just sent
    if (chatId.startsWith('group_') && m.recipientId === chatId && m.senderId !== userId && m.status === 'sent') {
        m.status = 'delivered';
        changed = true;
    }
  });
  if (changed) saveLocal(STORAGE_KEY_MESSAGES, messages);
};

export const markMessagesAsSeen = async (chatId: string, userId: string) => {
    const messages = getLocal(STORAGE_KEY_MESSAGES);
    let changed = false;
    messages.forEach((m: any) => {
      // For private chats:
      if (!chatId.startsWith('group_')) {
          const [u1, u2] = chatId.split('_');
          const isParticipant = (m.senderId === u1 && m.recipientId === u2) || (m.senderId === u2 && m.recipientId === u1);
          if (isParticipant && m.recipientId === userId && m.status !== 'seen') {
            m.status = 'seen';
            changed = true;
          }
      } else {
          // For groups:
          if (m.recipientId === chatId && m.senderId !== userId && m.status !== 'seen') {
            m.status = 'seen';
            changed = true;
          }
      }
    });
    if (changed) saveLocal(STORAGE_KEY_MESSAGES, messages);
  };

export const getMessages = async (chatId: string) => {
  const all = getLocal(STORAGE_KEY_MESSAGES);
  if (chatId.startsWith('group_')) {
    return all.filter((m: any) => m.recipientId === chatId);
  }
  const [u1, u2] = chatId.split('_');
  return all.filter((m: any) => 
    (m.senderId === u1 && m.recipientId === u2) || (m.senderId === u2 && m.recipientId === u1)
  );
};

export const getMyChats = async (uid: string) => {
  const chats = getLocal(STORAGE_KEY_CHATS);
  return chats.filter((c: any) => c.participants.includes(uid))
              .sort((a: any, b: any) => b.updatedAt - a.updatedAt);
};

export const getAllUsers = async () => getLocal(STORAGE_KEY_USERS).filter((u: any) => !u.isGloballyBlocked);
export const getUserById = async (uid: string) => getLocal(STORAGE_KEY_USERS).find((u: any) => u.uid === uid);

// --- CALLS ---

export const initiateCall = async (callerId: string, receiverId: string, type: 'voice' | 'video') => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const callId = 'call_' + crypto.randomUUID();
  const newCall = {
    id: callId,
    callerId,
    receiverId,
    type,
    status: 'ringing',
    timestamp: Date.now()
  };
  calls.push(newCall);
  saveLocal(STORAGE_KEY_CALLS, calls);
  return newCall;
};

export const getIncomingCall = async (userId: string) => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  return calls.find((c: any) => c.receiverId === userId && c.status === 'ringing' && (Date.now() - c.timestamp) < 60000);
};

export const updateCallStatus = async (callId: string, status: 'accepted' | 'rejected' | 'ended') => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const idx = calls.findIndex((c: any) => c.id === callId);
  if (idx !== -1) {
    calls[idx].status = status;
    saveLocal(STORAGE_KEY_CALLS, calls);
    return calls[idx];
  }
  return null;
};

export const getCallById = async (callId: string) => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  return calls.find((c: any) => c.id === callId);
};

export const cleanOldCalls = () => {
  const calls = getLocal(STORAGE_KEY_CALLS);
  const filtered = calls.filter((c: any) => (Date.now() - c.timestamp) < 300000);
  if (filtered.length !== calls.length) {
    saveLocal(STORAGE_KEY_CALLS, filtered);
  }
};

// --- STORIES ---
export const addStory = async (story: any) => {
  const s = getLocal(STORAGE_KEY_STORIES);
  s.push({ ...story, likes: [] });
  saveLocal(STORAGE_KEY_STORIES, s.slice(-50));
};
export const getStories = async () => getLocal(STORAGE_KEY_STORIES).filter((s: any) => (Date.now() - s.timestamp) < 86400000);
export const likeStory = async (id: string, uid: string) => {
  const s = getLocal(STORAGE_KEY_STORIES);
  const i = s.findIndex((st: any) => st.id === id);
  if (i !== -1) {
    s[i].likes = s[i].likes || [];
    const li = s[i].likes.indexOf(uid);
    if (li === -1) s[i].likes.push(uid); else s[i].likes.splice(li, 1);
    saveLocal(STORAGE_KEY_STORIES, s);
  }
};
export const sendStoryReply = async (rid: string, sid: string, text: string, story: any) => {
  const msg = {
    id: 'm_' + Math.random().toString(36).substr(2, 9),
    senderId: sid, recipientId: rid, text, type: 'story_reply', 
    timestamp: Date.now(), status: 'sent',
    storyContext: { storyId: story.id, mediaUrl: story.mediaUrl, mediaType: story.mediaType }
  };
  await addMessage(msg);
  return msg;
};

// Utils
export const blockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = u[i].blockedUsers || [];
    if (!u[i].blockedUsers.includes(target)) u[i].blockedUsers.push(target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};
export const unblockUser = async (my: string, target: string) => {
  const u = getLocal(STORAGE_KEY_USERS);
  const i = u.findIndex((usr: any) => usr.uid === my);
  if (i !== -1) {
    u[i].blockedUsers = (u[i].blockedUsers || []).filter((id: string) => id !== target);
    saveLocal(STORAGE_KEY_USERS, u);
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Chat, Message } from '../../types';
import { MessageBubble } from './MessageBubble';
import { getAIResponse } from '../../gemini';
import { getUserById, addMessage, getMessages, toggleChatLock, markMessagesAsSeen, markMessagesAsDelivered } from '../../firebase';

interface ChatWindowProps {
  chat: Chat;
  currentUser: User;
  onClose: () => void;
  onUserClick: (user: User) => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

export const ChatWindow: React.FC<ChatWindowProps> = ({ chat, currentUser, onClose, onUserClick, onCallStart }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [otherUser, setOtherUser] = useState<User | null>(null);
  const [isLocked, setIsLocked] = useState(chat.lockedBy?.includes(currentUser.uid) || false);
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isGroup = chat.type === 'group';
  const otherId = !isGroup ? chat.participants.find(p => p !== currentUser.uid) || '' : chat.id;

  useEffect(() => {
    const sync = async () => {
      if (!isGroup && !otherUser) {
        const u = await getUserById(otherId);
        if (u) setOtherUser(u);
      }

      // Update local statuses for incoming messages
      await markMessagesAsDelivered(chat.id, currentUser.uid);
      await markMessagesAsSeen(chat.id, currentUser.uid);

      const msgs = await getMessages(chat.id);
      setMessages(prev => (JSON.stringify(prev) !== JSON.stringify(msgs) ? msgs : prev));
    };
    sync();
    const itv = setInterval(sync, 2000);
    return () => clearInterval(itv);
  }, [chat.id, otherId, isGroup, currentUser.uid]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [messages, isTyping, isUploading]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    const text = inputText.trim();
    if (!text) return;
    const msg: Message = {
      id: 'm_' + Math.random().toString(36).substr(2, 9),
      senderId: currentUser.uid,
      recipientId: isGroup ? chat.id : otherId,
      text, type: 'text', timestamp: Date.now(), status: 'sent'
    };
    setMessages(prev => [...prev, msg]);
    setInputText('');
    await addMessage(msg);

    if (text.toLowerCase().startsWith('/ai')) {
      setIsTyping(true);
      try {
        const res = await getAIResponse(text.replace('/ai', '').trim());
        const aiMsg: Message = {
          id: 'ai_' + Date.now(),
          senderId: 'gemini_ai',
          recipientId: isGroup ? chat.id : currentUser.uid,
          text: res || "I'm thinking...", 
          type: 'text', timestamp: Date.now(), status: 'seen'
        };
        await addMessage(aiMsg);
      } catch (err) {
        console.error("AI Error:", err);
      } finally {
        setIsTyping(false);
      }
    }
  };

  const handleFileClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const fileUrl = event.target?.result as string;

        let messageType: any = 'file';
        if (file.type.startsWith('image/')) messageType = 'image';
        else if (file.type.startsWith('video/')) messageType = 'video';

        const msg: Message = {
          id: 'f_' + Math.random().toString(36).substr(2, 9),
          senderId: currentUser.uid,
          recipientId: isGroup ? chat.id : otherId,
          text: file.name,
          type: messageType,
          timestamp: Date.now(),
          status: 'sent',
          fileUrl: fileUrl,
          fileName: file.name
        };
        setMessages(prev => [...prev, msg]);
        await addMessage(msg);
        setIsUploading(false);
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error("File upload error:", err);
      setIsUploading(false);
    }
    e.target.value = '';
  };

  const handleToggleLock = async () => {
    if (!currentUser.chatLockPassword) {
      alert("Please set a Chat Lock Password in Settings first!");
      return;
    }
    await toggleChatLock(chat.id, currentUser.uid);
    setIsLocked(!isLocked);
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-slate-50 dark:bg-slate-900/40 animate-in fade-in duration-300">
      <div className="p-3 md:p-4 flex items-center justify-between glass z-10 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center gap-3">
          <button onClick={onClose} className="lg:hidden p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" /></svg>
          </button>

          <div className="relative cursor-pointer" onClick={() => !isGroup && otherUser && onUserClick(otherUser)}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" alt="Profile" />
            {!isGroup && otherUser?.status === 'online' && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>}
          </div>

          <div className="min-w-0">
            <h3 className="font-bold text-sm leading-none flex items-center gap-2 truncate">
              {isGroup ? chat.name : otherUser?.name}
              {isLocked && <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>}
            </h3>
            <span className="text-[10px] text-slate-500 font-medium">{isGroup ? `${chat.participants.length} members` : (otherUser?.status === 'online' ? 'Online' : 'Offline')}</span>
          </div>
        </div>

        <div className="flex items-center gap-1">
          {!isGroup && otherUser && onCallStart && (
            <>
              <button onClick={() => onCallStart(otherUser, 'voice')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
              </button>
              <button onClick={() => onCallStart(otherUser, 'video')} className="p-2.5 hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
              </button>
            </>
          )}
          <button onClick={handleToggleLock} className={`p-2.5 rounded-xl transition-all ${isLocked ? 'bg-indigo-500 text-white' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </button>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 scroll-smooth">
        {messages.length === 0 && !isTyping && !isUploading && (
          <div className="h-full flex flex-col items-center justify-center opacity-40 text-center p-8">
            <div className="w-16 h-16 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
            </div>
            <p className="text-sm font-medium">No messages yet. Say hi!</p>
          </div>
        )}
        {messages.map((msg, index) => (
          <MessageBubble key={msg.id || index} message={msg} isOwn={msg.senderId === currentUser.uid} isAI={msg.senderId === 'gemini_ai'} onReply={() => {}} onForward={() => {}} />
        ))}
        {(isTyping || isUploading) && (
          <div className="flex items-center gap-2 ml-2 animate-in fade-in slide-in-from-left-2">
            <div className="flex gap-1">
              <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></div>
            </div>
            {isUploading && <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Uploading...</span>}
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-3 md:p-4 glass border-t border-slate-200 dark:border-slate-800 flex gap-2 md:gap-3 items-center">
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          className="hidden" 
        />
        <button 
          type="button"
          onClick={handleFileClick}
          className="p-3 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-2xl transition-all active:scale-90 shrink-0"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.414a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
          </svg>
        </button>
        <input 
          type="text" 
          value={inputText} 
          onChange={e => setInputText(e.target.value)} 
          placeholder="Type a message..." 
          className="flex-1 bg-slate-100 dark:bg-slate-800/50 rounded-2xl px-5 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all border border-transparent" 
        />
        <button type="submit" disabled={!inputText.trim() && !isUploading} className="p-3 bg-indigo-500 text-white rounded-2xl hover:bg-indigo-600 disabled:opacity-40 active:scale-90 transition-all shadow-lg shrink-0">
          <svg className="w-5 h-5 rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
        </button>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Chat, Story, CallSession } from '../../types';
import { Sidebar } from './Sidebar';
import { ChatWindow } from './ChatWindow';
import { ProfilePanel } from './ProfilePanel';
import { StoryUpload } from './StoryUpload';
import { StoryViewer } from './StoryViewer';
import { PublicProfile } from './PublicProfile';
import { CallModal } from './CallModal';
import { initiateCall, getIncomingCall, getUserById, updateCallStatus, cleanOldCalls } from '../../firebase';

interface ChatDashboardProps {
  currentUser: User;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ChatDashboard: React.FC<ChatDashboardProps> = ({ currentUser, toggleDarkMode, isDarkMode }) => {
  const [selectedChat, setSelectedChat] = useState<Chat | null>(null);
  const [showProfile, setShowProfile] = useState(false);
  const [showStoryUpload, setShowStoryUpload] = useState(false);
  const [viewingStories, setViewingStories] = useState<Story[] | null>(null);
  const [viewingUser, setViewingUser] = useState<User | null>(null);
  const [activeCall, setActiveCall] = useState<CallSession | null>(null);

  // Poll for incoming calls
  useEffect(() => {
    const poll = async () => {
      cleanOldCalls();
      if (activeCall) return; // Don't interrupt existing call

      const incoming = await getIncomingCall(currentUser.uid);
      if (incoming) {
        const caller = await getUserById(incoming.callerId);
        if (caller) {
          setActiveCall({
            id: incoming.id,
            partner: caller,
            type: incoming.type,
            callerId: incoming.callerId,
            receiverId: incoming.receiverId,
            status: incoming.status,
            isIncoming: true,
            timestamp: incoming.timestamp
          });
        }
      }
    };

    const itv = setInterval(poll, 3000);
    return () => clearInterval(itv);
  }, [currentUser.uid, activeCall]);

  const startCall = async (user: User, type: 'voice' | 'video') => {
    const call = await initiateCall(currentUser.uid, user.uid, type);
    setActiveCall({ 
      id: call.id,
      partner: user, 
      type, 
      callerId: currentUser.uid,
      receiverId: user.uid,
      status: 'ringing',
      isIncoming: false,
      timestamp: call.timestamp
    });
  };

  const handleCallEnd = async () => {
    if (activeCall) {
      await updateCallStatus(activeCall.id, 'ended');
      setActiveCall(null);
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 dark:bg-slate-950 transition-colors duration-300 overflow-hidden">
      {/* Sidebar */}
      <div className={`${selectedChat ? 'hidden lg:flex' : 'flex'} w-full lg:w-96 h-full shrink-0 border-r border-slate-200 dark:border-slate-800 shadow-xl z-20`}>
        <Sidebar 
          currentUser={currentUser} 
          onChatSelect={setSelectedChat} 
          onProfileClick={() => setShowProfile(true)}
          activeChatId={selectedChat?.id}
          onStoryUpload={() => setShowStoryUpload(true)}
          onStoryView={setViewingStories}
          onUserClick={setViewingUser}
          toggleDarkMode={toggleDarkMode}
          isDarkMode={isDarkMode}
        />
      </div>

      {/* Main Chat Area */}
      <div className={`${!selectedChat ? 'hidden lg:flex' : 'flex'} flex-1 h-full relative overflow-hidden bg-slate-100/30 dark:bg-slate-900/40`}>
        {selectedChat ? (
          <ChatWindow 
            chat={selectedChat} 
            currentUser={currentUser} 
            onClose={() => setSelectedChat(null)}
            onUserClick={setViewingUser}
            onCallStart={startCall}
          />
        ) : (
          <div className="hidden lg:flex flex-1 flex-col items-center justify-center p-8 text-center h-full relative">
            <div className="absolute inset-0 opacity-5 dark:opacity-[0.02] pointer-events-none overflow-hidden">
                <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                    <path d="M0,0 L100,100 M100,0 L0,100" stroke="currentColor" strokeWidth="0.1" fill="none" />
                </svg>
            </div>
            <div className="w-32 h-32 bg-indigo-500/10 dark:bg-indigo-500/5 rounded-full flex items-center justify-center mb-8 animate-float">
              <svg className="w-16 h-16 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
              </svg>
            </div>
            <h2 className="text-3xl font-extrabold mb-3 bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-purple-600">Connect instantly.</h2>
            <p className="text-slate-500 dark:text-slate-400 max-w-sm text-lg font-medium leading-relaxed">
              Select a conversation to start chatting, or explore recent stories from your contacts.
            </p>
          </div>
        )}
      </div>

      {/* Overlays */}
      {showProfile && (
        <ProfilePanel 
          user={currentUser} 
          onClose={() => setShowProfile(false)} 
          toggleDarkMode={toggleDarkMode}
          isDarkMode={isDarkMode}
        />
      )}

      {showStoryUpload && (
        <StoryUpload 
          currentUser={currentUser} 
          onClose={() => setShowStoryUpload(false)} 
        />
      )}

      {viewingStories && (
        <StoryViewer 
          stories={viewingStories} 
          currentUser={currentUser}
          onClose={() => setViewingStories(null)} 
        />
      )}

      {viewingUser && (
        <PublicProfile 
          user={viewingUser} 
          onClose={() => setViewingUser(null)} 
          onCallStart={startCall}
        />
      )}

      {activeCall && (
        <CallModal 
          session={activeCall}
          onHangUp={handleCallEnd} 
        />
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat, Story } from '../../types';
import { StoryBar } from './StoryBar';
import { getAllUsers, getMyChats } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  onProfileClick: () => void;
  activeChatId?: string;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onUserClick: (user: User) => void;
  toggleDarkMode?: () => void;
  isDarkMode?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, onProfileClick, activeChatId, onStoryUpload, onStoryView, onUserClick, toggleDarkMode, isDarkMode
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [showGroupModal, setShowGroupModal] = useState(false);

  useEffect(() => {
    const sync = async () => {
      const users = await getAllUsers();
      const myBlocked = currentUser.blockedUsers || [];
      setAllUsers(users.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };
    sync();
    const itv = setInterval(sync, 4000);
    return () => clearInterval(itv);
  }, [currentUser]);

  const isRevealingLocked = currentUser.chatLockPassword && search === currentUser.chatLockPassword;

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    // Filter out locked chats unless secret key is entered
    const visibleChats = chats.filter(c => {
      const isLocked = c.lockedBy?.includes(currentUser.uid);
      if (isRevealingLocked) return isLocked; 
      return !isLocked;
    });

    if (!term || isRevealingLocked) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => u.name.toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      if (c.type === 'group') return c.name?.toLowerCase().includes(term);
      const otherId = c.participants.find(p => p !== currentUser.uid);
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers.filter(u => !chats.some(c => c.type === 'private' && c.participants.includes(u.uid))) };
  }, [search, allUsers, chats, currentUser.uid, isRevealingLocked]);

  const handleStartNewChat = (user: User) => {
    const existing = chats.find(c => c.type === 'private' && c.participants.includes(user.uid));
    if (existing) onChatSelect(existing);
    else onChatSelect({
      id: [currentUser.uid, user.uid].sort().join('_'),
      type: 'private', participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(), lockedBy: []
    });
    setSearch('');
  };

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { name: user?.name || 'Contact', photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, status: user?.status };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 z-10">
      <div className="p-4 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={onProfileClick}>
          <div className="relative">
            <img src={currentUser.photoURL} className="w-10 h-10 rounded-2xl object-cover border-2 border-transparent group-hover:border-indigo-500 transition-all shadow-md" alt="" />
            <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 shadow-sm"></div>
          </div>
          <div className="min-w-0">
            <h3 className="font-bold text-sm truncate">{currentUser.name}</h3>
            <span className="text-[10px] text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">Account Settings</span>
          </div>
        </div>
        <div className="flex items-center gap-1">
          {toggleDarkMode && (
            <button 
              onClick={toggleDarkMode} 
              className="p-2.5 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-all"
              title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {isDarkMode ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
          )}
          <button onClick={() => setShowGroupModal(true)} className="p-2.5 text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-xl transition-all" title="Create New Group">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          </button>
        </div>
      </div>

      <StoryBar currentUser={currentUser} onUploadClick={onStoryUpload} onStoryClick={onStoryView} />

      <div className="p-4">
        <div className="relative group">
          <span className="absolute inset-y-0 left-3.5 flex items-center text-slate-400 group-focus-within:text-indigo-500 transition-colors">
            {isRevealingLocked ? (
              <svg className="w-4 h-4 text-indigo-500 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
            ) : (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            )}
          </span>
          <input 
            type="text" placeholder={isRevealingLocked ? "Secret Vault Unlocked" : "Search chats or people..."}
            value={search} onChange={(e) => setSearch(e.target.value)}
            className={`w-full border-none rounded-2xl py-3 pl-11 pr-4 text-sm outline-none transition-all shadow-sm ${isRevealingLocked ? 'bg-indigo-50 dark:bg-indigo-900/30 ring-2 ring-indigo-500' : 'bg-slate-100/80 dark:bg-slate-800/80 focus:ring-2 focus:ring-indigo-500/40 focus:bg-white dark:focus:bg-slate-800'}`}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-0.5 px-3 pb-4">
        {isRevealingLocked && (
          <div className="px-4 py-3 bg-indigo-500/10 rounded-2xl mb-4 border border-indigo-500/20 text-center animate-in fade-in slide-in-from-top-2">
             <span className="text-[10px] font-black text-indigo-500 dark:text-indigo-400 uppercase tracking-[0.25em]">Private Vault Unlocked</span>
          </div>
        )}

        {searchResults.chats.length === 0 && searchResults.users.length === 0 && (
          <div className="py-20 text-center px-6">
            <p className="text-slate-400 dark:text-slate-500 text-sm font-medium">No conversations found.</p>
          </div>
        )}

        {searchResults.chats.map(chat => {
          const info = getChatInfo(chat);
          const isActive = activeChatId === chat.id;
          return (
            <div 
              key={chat.id} onClick={() => { onChatSelect(chat); if(isRevealingLocked) setSearch(''); }}
              className={`flex items-center gap-3.5 p-3.5 rounded-2xl cursor-pointer transition-all active:scale-[0.97] mb-0.5 ${isActive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
              <div className="relative flex-shrink-0">
                <img src={info.photo} className="w-12 h-12 rounded-[1.25rem] object-cover shadow-sm" alt="" />
                {info.status === 'online' && !isActive && <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 shadow-sm"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center">
                  <h4 className="font-bold text-[14px] truncate">{info.name}</h4>
                  <span className={`text-[9px] font-bold uppercase tracking-tight ${isActive ? 'text-white/70' : 'text-slate-400 dark:text-slate-500'}`}>
                    {chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}
                  </span>
                </div>
                <div className="flex items-center justify-between gap-2 mt-0.5">
                  <p className={`text-[12px] truncate font-medium ${isActive ? 'text-white/80' : 'text-slate-500 dark:text-slate-400'}`}>
                    {chat.lastMessage?.text || 'New conversation'}
                  </p>
                  {chat.lockedBy?.includes(currentUser.uid) && !isActive && (
                    <svg className="w-3 h-3 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {searchResults.users.map(u => (
          <div key={u.uid} onClick={() => handleStartNewChat(u)} className="flex items-center gap-3.5 p-3.5 rounded-2xl cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all group">
            <img src={u.photoURL} className="w-11 h-11 rounded-[1.1rem] object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
            <div className="flex-1 min-w-0">
              <h4 className="font-bold text-[14px] truncate">{u.name}</h4>
              <p className="text-[10px] text-slate-500 dark:text-slate-500 font-bold uppercase tracking-wider">{u.status === 'online' ? 'Available' : 'Offline'}</p>
            </div>
            <div className="p-2 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
               <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
            </div>
          </div>
        ))}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../../types';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward }) => {
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showMenu]);

  const formatTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message.text);
    setShowMenu(false);
  };

  const renderStatus = (isMedia?: boolean) => {
    if (!isOwn) return null;
    const colorClass = isMedia ? 'text-white/60' : 'text-slate-400 dark:text-slate-500';
    const seenColorClass = isMedia ? 'text-sky-300' : 'text-sky-500';

    switch (message.status) {
      case 'sent':
        return <svg className={`w-3.5 h-3.5 ${colorClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>;
      case 'delivered':
        return <div className="flex -space-x-2"><svg className={`w-3.5 h-3.5 ${colorClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg><svg className={`w-3.5 h-3.5 ${colorClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg></div>;
      case 'seen':
        return <div className="flex -space-x-2"><svg className={`w-3.5 h-3.5 ${seenColorClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg><svg className={`w-3.5 h-3.5 ${seenColorClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg></div>;
    }
  };

  const isMediaMessage = message.type === 'image' || message.type === 'video';

  return (
    <div className={`flex w-full ${isOwn ? 'justify-end' : 'justify-start'} mb-1.5 px-1 animate-in fade-in slide-in-from-bottom-1 duration-200`}>
      <div className={`flex flex-col max-w-[85%] md:max-w-[70%] group ${isOwn ? 'items-end' : 'items-start'} relative`}>

        {/* Interaction Menu */}
        {showMenu && (
          <div 
            ref={menuRef}
            className={`absolute z-50 bottom-full mb-3 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-700 p-1.5 flex flex-col min-w-[150px] animate-in zoom-in-95 duration-150 ${isOwn ? 'right-0' : 'left-0'}`}
          >
            <button onClick={() => { onReply(message); setShowMenu(false); }} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-blue-500/10 text-blue-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg></div>
              Reply
            </button>
            <button onClick={handleCopy} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-indigo-500/10 text-indigo-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1" /></svg></div>
              Copy Text
            </button>
            <button onClick={() => { onForward(message); setShowMenu(false); }} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-green-500/10 text-green-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></div>
              Forward
            </button>
          </div>
        )}

        <div 
          onClick={() => setShowMenu(!showMenu)}
          className={`relative rounded-[1.5rem] message-shadow transition-all duration-300 cursor-pointer active:scale-[0.98] overflow-hidden ${
            isMediaMessage ? 'p-1' : 'p-3.5'
          } ${
            isOwn 
            ? 'bg-gradient-to-br from-indigo-500 to-indigo-700 text-white rounded-tr-none' 
            : isAI
              ? 'bg-gradient-to-br from-purple-600 to-indigo-600 text-white rounded-tl-none ring-2 ring-purple-500/20 shadow-indigo-500/10'
              : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-tl-none border border-slate-200/50 dark:border-slate-700/50'
          }`}
        >
          {message.isForwarded && (
            <div className={`flex items-center gap-1.5 mb-1.5 opacity-60 text-[10px] font-bold italic ${isMediaMessage ? 'px-3 pt-1.5' : ''}`}>
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              Forwarded
            </div>
          )}

          {isAI && !message.isForwarded && (
            <div className={`flex items-center gap-2 mb-2 ${isMediaMessage ? 'px-3 pt-1.5' : ''}`}>
              <div className="w-5 h-5 bg-white/20 rounded-lg flex items-center justify-center">
                <svg className="w-3 h-3 text-white" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" />
                </svg>
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">Gemini Pro</span>
            </div>
          )}

          {/* Reply Context */}
          {message.replyContext && (
            <div className={`mb-2.5 p-3 rounded-2xl text-xs border-l-4 ${isOwn ? 'bg-indigo-800/40 border-indigo-300' : 'bg-slate-100 dark:bg-slate-700/50 border-indigo-500 shadow-inner'}`}>
              <div className="font-black text-indigo-500 dark:text-indigo-400 mb-1 flex items-center gap-2">
                 <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
                 {message.replyContext.senderName}
              </div>
              <p className="opacity-70 line-clamp-1 italic font-medium">{message.replyContext.text}</p>
            </div>
          )}

          {/* Integrated Media Elements */}
          {message.type === 'image' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-[1.25rem]">
              <img src={message.fileUrl} alt="Sent" className="w-full max-h-96 object-cover hover:scale-105 transition-transform duration-500" />
              <div className="absolute bottom-3 right-3 px-2.5 py-1 bg-black/40 backdrop-blur-md rounded-full flex items-center gap-2 border border-white/10">
                <span className="text-[10px] font-black text-white uppercase">{formatTime(message.timestamp)}</span>
                {renderStatus(true)}
              </div>
            </div>
          )}

          {message.type === 'video' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-[1.25rem] bg-black">
              <video src={message.fileUrl} className="w-full max-h-96 object-contain" controls />
              <div className="absolute bottom-3 right-3 px-2.5 py-1 bg-black/40 backdrop-blur-md rounded-full flex items-center gap-2 border border-white/10 z-10">
                <span className="text-[10px] font-black text-white uppercase">{formatTime(message.timestamp)}</span>
                {renderStatus(true)}
              </div>
            </div>
          )}

          {message.type === 'file' && (
            <div className={`mb-1 p-3 rounded-2xl flex items-center gap-3.5 border ${isOwn ? 'bg-white/10 border-white/10' : 'bg-slate-50 dark:bg-slate-700/30 border-slate-100 dark:border-slate-600/50 shadow-sm'}`}>
                <div className="w-11 h-11 rounded-xl bg-indigo-500/10 dark:bg-indigo-500/20 flex items-center justify-center text-indigo-500 shrink-0">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold truncate">{message.fileName || 'Document'}</p>
                    <p className="text-[9px] font-black uppercase tracking-widest opacity-60">File Transfer</p>
                </div>
                <a href={message.fileUrl} download className="p-2.5 rounded-xl hover:bg-black/5 dark:hover:bg-white/5 transition-all">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
            </div>
          )}

          {message.type === 'text' && (
            <p className="text-[14px] leading-[1.6] font-medium whitespace-pre-wrap">{message.text}</p>
          )}

          {!isMediaMessage && (
            <div className={`flex items-center gap-2 mt-1.5 ${isOwn ? 'justify-end' : 'justify-start'}`}>
              <span className={`text-[9px] font-bold uppercase tracking-wider opacity-60`}>
                {formatTime(message.timestamp)}
              </span>
              {renderStatus()}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile } from '../../firebase';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode }) => {
  const { logout } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || 'Available');
  const [lockPass, setLockPass] = useState(user.chatLockPassword || '');
  const [newPhoto, setNewPhoto] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const size = 300; 
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, size, size);
        const compressed = canvas.toDataURL('image/jpeg', 0.7);
        setNewPhoto(compressed);
      };
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!name.trim()) {
      alert("Name cannot be empty");
      return;
    }
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name: name.trim(),
        bio: bio.trim(),
        chatLockPassword: lockPass.trim(),
        photoURL: newPhoto || user.photoURL
      });
      setIsEditing(false);
    } catch (err) {
      alert("Error saving profile");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className={`fixed inset-0 z-50 flex transition-all duration-500 ${isEditing ? 'items-center justify-center p-4' : 'justify-end'}`}>
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity duration-500 ${isEditing ? 'opacity-100' : 'opacity-100'}`} 
        onClick={() => !isSaving && onClose()}
      ></div>

      {/* Panel / Modal Container */}
      <div 
        className={`relative bg-white dark:bg-slate-900 shadow-2xl flex flex-col transition-all duration-500 overflow-hidden ${
          isEditing 
          ? 'w-full max-w-xl h-auto max-h-[90vh] rounded-[3rem] animate-in zoom-in-95' 
          : 'w-full max-w-sm h-full animate-slide-left'
        }`}
      >
        {/* Header */}
        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-white/50 dark:bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
          <h2 className="text-xl font-bold">{isEditing ? 'Edit Profile' : 'Settings'}</h2>
          <button 
            onClick={() => isEditing ? setIsEditing(false) : onClose()} 
            className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 md:p-8 space-y-8 no-scrollbar">
          {isEditing ? (
            /* FULL EDITING INTERFACE */
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex flex-col items-center gap-6">
                <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                  <div className="w-32 h-32 md:w-40 md:h-40 rounded-[3.5rem] overflow-hidden border-4 border-indigo-500/20 shadow-2xl">
                    <img src={newPhoto || user.photoURL} className="w-full h-full object-cover transition-all group-hover:brightness-75" alt="" />
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                      <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                      </svg>
                    </div>
                  </div>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoSelect} />
                  <div className="absolute -bottom-2 -right-2 bg-indigo-600 p-3 rounded-2xl text-white shadow-xl border-4 border-white dark:border-slate-900">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em] ml-2">Full Name</label>
                  <input 
                    type="text" 
                    value={name} 
                    onChange={e => setName(e.target.value)}
                    placeholder="Enter your name"
                    className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 font-bold outline-none ring-2 ring-transparent focus:ring-indigo-500/30 transition-all border border-transparent focus:bg-white dark:focus:bg-slate-800"
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em] ml-2">About / Bio</label>
                  <textarea 
                    value={bio} 
                    onChange={e => setBio(e.target.value)}
                    placeholder="Tell us about yourself"
                    className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 text-sm font-medium outline-none ring-2 ring-transparent focus:ring-indigo-500/30 transition-all border border-transparent focus:bg-white dark:focus:bg-slate-800 resize-none"
                    rows={3}
                  />
                </div>

                <div className="bg-indigo-500/5 p-6 rounded-[2rem] border border-indigo-500/10 space-y-3">
                  <div className="flex items-center gap-2 mb-1">
                    <svg className="w-4 h-4 text-indigo-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2 v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                    <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em]">Privacy: Chat Vault Key</label>
                  </div>
                  <input 
                    type="password" 
                    value={lockPass} 
                    onChange={e => setLockPass(e.target.value)}
                    placeholder="Enter Secret Password"
                    className="w-full bg-white dark:bg-slate-800 rounded-xl px-5 py-3 text-sm font-mono border border-indigo-500/20 outline-none focus:ring-2 focus:ring-indigo-500/40"
                  />
                  <p className="text-[9px] text-slate-500 font-medium px-1">Tip: Use this key in the search bar to reveal hidden conversations.</p>
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => { setIsEditing(false); setNewPhoto(null); }} 
                  disabled={isSaving}
                  className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-sm font-bold hover:bg-slate-200 dark:hover:bg-slate-700 transition-all active:scale-95"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleSave} 
                  disabled={isSaving}
                  className="flex-[2] py-4 bg-indigo-500 text-white rounded-2xl text-sm font-bold shadow-xl shadow-indigo-500/30 hover:bg-indigo-600 transition-all active:scale-95 flex items-center justify-center gap-2"
                >
                  {isSaving ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                      <span>Saving...</span>
                    </>
                  ) : (
                    'Save Changes'
                  )}
                </button>
              </div>
            </div>
          ) : (
            /* SIDEBAR VIEW INTERFACE */
            <div className="space-y-8 animate-in fade-in duration-500">
              <div className="flex flex-col items-center text-center">
                <div className="relative mb-6">
                  <img src={user.photoURL} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl ring-4 ring-indigo-500/10" alt="" />
                  <div className="absolute bottom-0 right-0 w-8 h-8 bg-green-500 rounded-full border-4 border-white dark:border-slate-900 shadow-md"></div>
                </div>

                <h3 className="text-2xl font-black tracking-tight">{user.name}</h3>
                <p className="text-sm text-slate-500 mt-2 max-w-[240px] mx-auto leading-relaxed font-medium">{user.bio || 'Available'}</p>

                <button 
                  onClick={() => setIsEditing(true)} 
