);

import React, { useState, useEffect } from 'react';
import { User, Story, Chat } from '../../types';
import { getStories, getMyChats } from '../../firebase';

interface StatusViewProps {
  currentUser: User;
  onStoryUpload: () => void;
  onStoryView: (stories: Story[]) => void;
  onChatSelect: (chat: Chat) => void;
}

export const StatusView: React.FC<StatusViewProps> = ({ currentUser, onStoryUpload, onStoryView, onChatSelect }) => {
  const [stories, setStories] = useState<Story[]>([]);
  const [groups, setGroups] = useState<Chat[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      const [storyData, chatData] = await Promise.all([
        getStories(),
        getMyChats(currentUser.uid)
      ]);
      setStories(storyData);
      setGroups(chatData.filter(c => c.type === 'group'));
      setIsLoading(false);
    };
    fetchData();
    const itv = setInterval(fetchData, 10000);
    return () => clearInterval(itv);
  }, [currentUser.uid]);

  // Group stories by user
  const userStoriesMap: Record<string, Story[]> = {};
  stories.forEach(story => {
    if (!userStoriesMap[story.userId]) userStoriesMap[story.userId] = [];
    userStoriesMap[story.userId].push(story);
  });

  const myStories = userStoriesMap[currentUser.uid] || [];
  const others = Object.keys(userStoriesMap).filter(id => id !== currentUser.uid);

  return (
    <div className="flex-1 flex flex-col bg-white dark:bg-slate-900 animate-in fade-in duration-500">
      <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <h2 className="text-2xl font-black tracking-tight">Status</h2>
        <button 
            onClick={onStoryUpload}
            className="p-3 bg-indigo-500 text-white rounded-2xl hover:bg-indigo-600 transition-all shadow-lg active:scale-95"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-8 no-scrollbar">
        {/* My Status */}
        <section>
          <h4 className="px-2 mb-4 text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">My Status</h4>
          <div 
            onClick={myStories.length > 0 ? () => onStoryView(myStories) : onStoryUpload}
            className="flex items-center gap-4 p-4 rounded-3xl bg-slate-50 dark:bg-slate-800/50 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all cursor-pointer group"
          >
            <div className={`relative w-14 h-14 rounded-full p-0.5 ${myStories.length > 0 ? 'bg-gradient-to-tr from-indigo-500 to-pink-500' : 'bg-slate-200 dark:bg-slate-700'}`}>
              <img src={currentUser.photoURL} className="w-full h-full rounded-full object-cover border-2 border-white dark:border-slate-900" alt="" />
              <div className="absolute -bottom-1 -right-1 bg-indigo-500 text-white rounded-full p-1 border-2 border-white dark:border-slate-900 shadow-md group-hover:scale-110 transition-transform">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              </div>
            </div>
            <div className="flex-1">
              <p className="font-bold text-sm">My Status</p>
              <p className="text-xs text-slate-500 font-medium">Tap to add or view update</p>
            </div>
          </div>
        </section>

        {/* Recent Updates */}
        <section>
          <h4 className="px-2 mb-4 text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Recent Updates</h4>
          {others.length === 0 ? (
            <div className="p-8 text-center text-slate-500 italic text-xs font-medium bg-slate-50/50 dark:bg-slate-800/20 rounded-[2rem]">
              No recent status updates from your contacts.
            </div>
          ) : (
            <div className="space-y-3">
              {others.map(uid => {
                const userStories = userStoriesMap[uid];
                const first = userStories[0];
                return (
                  <div 
                    key={uid}
                    onClick={() => onStoryView(userStories)}
                    className="flex items-center gap-4 p-4 rounded-3xl hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-all cursor-pointer border border-transparent hover:border-slate-100 dark:hover:border-slate-800 shadow-sm"
                  >
                    <div className="w-14 h-14 rounded-full bg-gradient-to-tr from-green-400 to-blue-500 p-0.5">
                      <img src={first.userPhoto} className="w-full h-full rounded-full object-cover border-2 border-white dark:border-slate-900" alt="" />
                    </div>
                    <div className="flex-1">
                      <p className="font-bold text-sm">{first.userName}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{new Date(first.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </section>

        {/* Groups Section */}
        <section className="pb-10">
          <div className="flex items-center justify-between px-2 mb-4">
            <h4 className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em]">Your Groups</h4>
            <span className="text-[9px] bg-indigo-500/10 text-indigo-500 px-2 py-0.5 rounded-full font-black uppercase">{groups.length} total</span>
          </div>
          {groups.length === 0 ? (
             <div className="p-8 text-center bg-slate-50 dark:bg-slate-800/30 rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-slate-800">
               <p className="text-xs text-slate-400 font-bold">You aren't in any groups yet.</p>
             </div>
          ) : (
            <div className="grid grid-cols-1 gap-3">
              {groups.map(group => (
                <div 
                  key={group.id}
                  onClick={() => onChatSelect(group)}
                  className="flex items-center gap-4 p-4 rounded-3xl bg-white dark:bg-slate-800/30 border border-slate-100 dark:border-slate-700/50 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 hover:border-indigo-200 transition-all cursor-pointer group shadow-sm"
                >
                  <img src={group.groupIcon || `https://picsum.photos/seed/${group.id}/200`} className="w-12 h-12 rounded-2xl object-cover shadow-md group-hover:scale-110 transition-transform" alt="" />
                  <div className="flex-1 min-w-0">
                    <p className="font-bold text-sm truncate">{group.name}</p>
                    <p className="text-[10px] text-slate-500 font-medium truncate">
                      {group.lastMessage ? `${group.lastMessage.text}` : 'No messages yet'}
                    </p>
                  </div>
                  <div className="p-2 bg-indigo-500/10 rounded-xl text-indigo-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Chat } from '../../types';
import { getAllUsers, getMyChats } from '../../firebase';
import { CreateGroupModal } from './CreateGroupModal';

interface SidebarProps {
  currentUser: User;
  onChatSelect: (chat: Chat) => void;
  activeChatId?: string;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentUser, onChatSelect, activeChatId
}) => {
  const [search, setSearch] = useState('');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [chats, setChats] = useState<Chat[]>([]);
  const [showGroupModal, setShowGroupModal] = useState(false);

  useEffect(() => {
    const sync = async () => {
      const users = await getAllUsers();
      const myBlocked = currentUser.blockedUsers || [];
      setAllUsers(users.filter(u => u.uid !== currentUser.uid && !myBlocked.includes(u.uid)));
      const myChats = await getMyChats(currentUser.uid);
      setChats(myChats);
    };
    sync();
    const itv = setInterval(sync, 4000);
    return () => clearInterval(itv);
  }, [currentUser]);

  const isRevealingLocked = currentUser.chatLockPassword && search === currentUser.chatLockPassword;

  const searchResults = useMemo(() => {
    const term = search.toLowerCase().trim();

    const visibleChats = chats.filter(c => {
      const isLocked = c.lockedBy?.includes(currentUser.uid);
      if (isRevealingLocked) return isLocked; 
      return !isLocked;
    });

    if (!term || isRevealingLocked) return { chats: visibleChats, users: [] };

    const matchedUsers = allUsers.filter(u => u.name.toLowerCase().includes(term));
    const matchedChats = visibleChats.filter(c => {
      if (c.type === 'group') return c.name?.toLowerCase().includes(term);
      const otherId = c.participants.find(p => p !== currentUser.uid);
      const user = allUsers.find(u => u.uid === otherId);
      return user?.name.toLowerCase().includes(term);
    });

    return { chats: matchedChats, users: matchedUsers.filter(u => !chats.some(c => c.type === 'private' && c.participants.includes(u.uid))) };
  }, [search, allUsers, chats, currentUser.uid, isRevealingLocked]);

  const handleStartNewChat = (user: User) => {
    const existing = chats.find(c => c.type === 'private' && c.participants.includes(user.uid));
    if (existing) onChatSelect(existing);
    else onChatSelect({
      id: [currentUser.uid, user.uid].sort().join('_'),
      type: 'private', participants: [currentUser.uid, user.uid],
      updatedAt: Date.now(), lockedBy: []
    });
    setSearch('');
  };

  const getChatInfo = (chat: Chat) => {
    if (chat.type === 'group') return { name: chat.name || 'Group', photo: chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200` };
    const otherId = chat.participants.find(p => p !== currentUser.uid);
    const user = allUsers.find(u => u.uid === otherId);
    return { name: user?.name || 'Contact', photo: user?.photoURL || `https://picsum.photos/seed/${otherId}/200`, status: user?.status };
  };

  return (
    <div className="w-full h-full flex flex-col bg-white dark:bg-slate-900 animate-in slide-in-from-left duration-300">
      <div className="p-6 flex items-center justify-between border-b border-slate-100 dark:border-slate-800">
        <h2 className="text-2xl font-black tracking-tight">Chats</h2>
        <button onClick={() => setShowGroupModal(true)} className="p-3 bg-indigo-50 text-indigo-500 dark:bg-indigo-500/10 rounded-2xl hover:bg-indigo-100 transition-all shadow-sm active:scale-95">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      <div className="p-4">
        <div className="relative group">
          <span className="absolute inset-y-0 left-3.5 flex items-center text-slate-400 group-focus-within:text-indigo-500 transition-colors">
            {isRevealingLocked ? (
              <svg className="w-4 h-4 text-indigo-500 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
            ) : (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            )}
          </span>
          <input 
            type="text" placeholder={isRevealingLocked ? "Secret Vault Unlocked" : "Search conversations..."}
            value={search} onChange={(e) => setSearch(e.target.value)}
            className={`w-full border-none rounded-2xl py-3.5 pl-11 pr-4 text-sm outline-none transition-all shadow-sm ${isRevealingLocked ? 'bg-indigo-50 dark:bg-indigo-900/30 ring-2 ring-indigo-500' : 'bg-slate-100/80 dark:bg-slate-800/80 focus:ring-2 focus:ring-indigo-500/40 focus:bg-white dark:focus:bg-slate-800'}`}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-0.5 px-3 pb-20 no-scrollbar">
        {isRevealingLocked && (
          <div className="px-4 py-3 bg-indigo-500/10 rounded-2xl mb-4 border border-indigo-500/20 text-center animate-in fade-in slide-in-from-top-2">
             <span className="text-[10px] font-black text-indigo-500 dark:text-indigo-400 uppercase tracking-[0.25em]">Private Vault Unlocked</span>
          </div>
        )}

        {searchResults.chats.length === 0 && searchResults.users.length === 0 && (
          <div className="py-20 text-center px-6">
            <p className="text-slate-400 dark:text-slate-500 text-sm font-medium">No conversations found.</p>
          </div>
        )}

        {searchResults.chats.map(chat => {
          const info = getChatInfo(chat);
          const isActive = activeChatId === chat.id;
          return (
            <div 
              key={chat.id} onClick={() => { onChatSelect(chat); if(isRevealingLocked) setSearch(''); }}
              className={`flex items-center gap-3.5 p-4 rounded-[2rem] cursor-pointer transition-all active:scale-[0.97] mb-1.5 ${isActive ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'}`}
            >
              <div className="relative flex-shrink-0">
                <img src={info.photo} className="w-14 h-14 rounded-2xl object-cover shadow-sm" alt="" />
                {info.status === 'online' && !isActive && <div className="absolute -bottom-0.5 -right-0.5 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-slate-900 shadow-sm"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center">
                  <h4 className="font-bold text-[15px] truncate">{info.name}</h4>
                  <span className={`text-[9px] font-bold uppercase tracking-tight ${isActive ? 'text-white/70' : 'text-slate-400 dark:text-slate-500'}`}>
                    {chat.lastMessage ? new Date(chat.lastMessage.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : ''}
                  </span>
                </div>
                <div className="flex items-center justify-between gap-2 mt-0.5">
                  <p className={`text-[13px] truncate font-medium ${isActive ? 'text-white/80' : 'text-slate-500 dark:text-slate-400'}`}>
                    {chat.lastMessage?.text || 'Start chatting...'}
                  </p>
                  {chat.lockedBy?.includes(currentUser.uid) && !isActive && (
                    <svg className="w-3.5 h-3.5 text-indigo-500 shrink-0" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {searchResults.users.map(u => (
          <div key={u.uid} onClick={() => handleStartNewChat(u)} className="flex items-center gap-3.5 p-4 rounded-[2rem] cursor-pointer hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all group">
            <img src={u.photoURL} className="w-14 h-14 rounded-2xl object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
            <div className="flex-1 min-w-0">
              <h4 className="font-bold text-[15px] truncate">{u.name}</h4>
              <p className="text-[10px] text-slate-500 dark:text-slate-500 font-bold uppercase tracking-wider">{u.status === 'online' ? 'Available' : 'Last seen recently'}</p>
            </div>
            <div className="p-2 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
               <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5l7 7-7 7" /></svg>
            </div>
          </div>
        ))}
      </div>

      {showGroupModal && <CreateGroupModal currentUser={currentUser} onClose={() => setShowGroupModal(false)} onCreated={onChatSelect} />}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { User } from '../../types';
import { useAuth } from '../../hooks/useAuth';
import { updateProfile } from '../../firebase';

interface ProfilePanelProps {
  user: User;
  onClose: () => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
  isTabMode?: boolean;
}

export const ProfilePanel: React.FC<ProfilePanelProps> = ({ user, onClose, toggleDarkMode, isDarkMode, isTabMode }) => {
  const { logout } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || 'Available');
  const [lockPass, setLockPass] = useState(user.chatLockPassword || '');
  const [newPhoto, setNewPhoto] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const size = 300; 
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, size, size);
        const compressed = canvas.toDataURL('image/jpeg', 0.7);
        setNewPhoto(compressed);
      };
    };
    reader.readAsDataURL(file);
  };

  const handleSave = async () => {
    if (!name.trim()) return;
    setIsSaving(true);
    try {
      await updateProfile(user, {
        name: name.trim(),
        bio: bio.trim(),
        chatLockPassword: lockPass.trim(),
        photoURL: newPhoto || user.photoURL
      });
      setIsEditing(false);
    } catch (err) {
      alert("Error saving profile");
    } finally {
      setIsSaving(false);
    }
  };

  const content = (
    <div className={`flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300`}>
      <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <h2 className="text-2xl font-black tracking-tight">{isEditing ? 'Edit Profile' : 'Settings'}</h2>
        {!isTabMode && (
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar pb-24">
        {isEditing ? (
          <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col items-center gap-6">
              <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-indigo-500/20 shadow-2xl">
                  <img src={newPhoto || user.photoURL} className="w-full h-full object-cover transition-all group-hover:brightness-75" alt="" />
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                    <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                </div>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoSelect} />
              </div>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em] ml-2">Display Name</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 font-bold outline-none border border-transparent focus:ring-2 focus:ring-indigo-500/30 transition-all" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em] ml-2">Bio</label>
                <textarea value={bio} onChange={e => setBio(e.target.value)} className="w-full bg-slate-100 dark:bg-slate-800 rounded-2xl px-6 py-4 text-sm font-medium outline-none resize-none" rows={3} />
              </div>
              <div className="bg-indigo-500/5 p-5 rounded-[2rem] border border-indigo-500/10 space-y-3">
                <label className="text-[10px] font-black uppercase text-indigo-500 tracking-[0.2em] ml-1 flex items-center gap-2">
                   <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M12 17c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm6-9h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2 v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6-5c1.66 0 3 1.34 3 3v2H9V6c0-1.66 1.34-3 3-3z"/></svg>
                   Chat Vault Key
                </label>
