                  </div>
                  <span className="text-sm font-bold">Dark Appearance</span>
                </div>
                <div className={`w-12 h-6 rounded-full transition-all relative ${isDarkMode ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-md transition-all ${isDarkMode ? 'left-7' : 'left-1'}`}></div>
                </div>
              </div>

              <button onClick={logout} className="w-full p-5 bg-red-50 dark:bg-red-900/10 text-red-500 rounded-3xl text-sm font-bold flex items-center gap-4 hover:bg-red-100 transition-all">
                <div className="p-3 bg-white dark:bg-red-900/20 shadow-sm rounded-xl">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                </div>
                Logout Account
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );

  if (isTabMode) return content;

  return (
    <div className={`fixed inset-0 z-50 flex justify-end`}>
      <div className={`absolute inset-0 bg-slate-900/60 backdrop-blur-md`} onClick={onClose}></div>
      <div className={`relative bg-white dark:bg-slate-900 shadow-2xl flex flex-col w-full max-w-sm h-full animate-slide-left`}>
        {content}
      </div>
    </div>
  );
};

