export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [showViewers, setShowViewers] = useState(false);

  const story = stories[currentIndex];
  const isOwner = story.userId === currentUser.uid;

  useEffect(() => {
    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);
    setShowViewers(false);

    // Track view if not owner
    if (!isOwner) {
      viewStory(story.id, currentUser.uid, currentUser.name);
    }

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story.id]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    if (customText) {
      setTimeout(handleNext, 800);
    }
  };

  const toggleViewersList = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!isOwner) return;
    setIsPaused(!showViewers ? true : false);
    setShowViewers(!showViewers);
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col h-[100dvh] transition-all overflow-hidden touch-none">
      {/* Top Header - Progress Bars & User Info */}
      <div className="absolute top-0 inset-x-0 z-50 pt-safe bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex gap-1 p-3">
          {stories.map((_, idx) => {
            const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
            return (
              <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-white transition-all duration-100 ease-linear"
                  style={{ width: barWidth }}
                />
              </div>
            );
          })}
        </div>

        <div className="px-4 pb-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img src={story.userPhoto} className="w-10 h-10 rounded-full border border-white/20 object-cover" alt="" />
            <div>
              <h4 className="text-white font-bold text-sm leading-none mb-1">{story.userName}</h4>
              <span className="text-white/60 text-[10px] uppercase font-bold tracking-widest">
                {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
            {(isPaused && !showViewers) && (
              <div className="ml-2 px-2 py-0.5 bg-white/20 backdrop-blur-md rounded-md text-[9px] text-white font-bold uppercase tracking-wider animate-pulse">
                Paused
              </div>
            )}
          </div>
          <button onClick={onClose} className="p-2 text-white/70 hover:text-white transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex items-center justify-center relative bg-black">
        {/* Navigation Zones */}
        {!showViewers && (
          <>
            <div className="absolute inset-y-0 left-0 w-1/4 z-30 cursor-pointer" onClick={handlePrev} />
            <div className="absolute inset-y-0 right-0 w-1/4 z-30 cursor-pointer" onClick={handleNext} />
          </>
        )}

        {showHeartAnim && (
          <div className="absolute z-40 animate-ping">
            <svg className="w-32 h-32 text-red-500" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        {showSentAnim && (
          <div className="absolute z-50 bg-indigo-600 px-6 py-3 rounded-full text-white font-bold shadow-2xl animate-in zoom-in duration-200">
            Sent! ✨
          </div>
        )}

        <div className="w-full h-full flex items-center justify-center">
          {story.mediaType === 'video' ? (
            <video 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain" 
              autoPlay 
              playsInline 
              muted={false}
              onPlay={() => !isPaused && setIsPaused(false)}
            />
          ) : (
            <img 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain" 
              alt="" 
              onDoubleClick={handleLike}
            />
          )}
        </div>

        {story.caption && !replyText && !showViewers && (
          <div className="absolute bottom-24 inset-x-0 p-8 text-center bg-gradient-to-t from-black/80 to-transparent z-40">
            <p className="text-white text-lg font-medium drop-shadow-lg">{story.caption}</p>
          </div>
        )}

        {/* Viewers List Overlay */}
        {showViewers && (
          <div className="absolute inset-0 z-[60] flex flex-col items-center justify-end animate-in slide-in-from-bottom duration-300">
             <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => { setShowViewers(false); setIsPaused(false); }}></div>
             <div className="relative w-full max-w-lg bg-white dark:bg-slate-900 rounded-t-[3rem] h-[60%] flex flex-col overflow-hidden shadow-2xl">
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
                   <h3 className="text-xl font-black">Viewers ({story.views?.length || 0})</h3>
                   <button onClick={() => { setShowViewers(false); setIsPaused(false); }} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
                   </button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
                   {(!story.views || story.views.length === 0) ? (
                      <div className="flex flex-col items-center justify-center h-full text-slate-400 gap-4">
                         <div className="p-4 bg-slate-50 dark:bg-slate-800 rounded-full"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></div>
                         <p className="text-sm font-bold uppercase tracking-widest">No views yet</p>
                      </div>
                   ) : (
                      story.views.sort((a,b) => b.timestamp - a.timestamp).map(v => (
                         <div key={v.userId} className="flex items-center gap-4 p-4 rounded-3xl bg-slate-50 dark:bg-slate-800/50 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all border border-transparent hover:border-indigo-100 dark:hover:border-indigo-900/20">
                            <img src={`https://picsum.photos/seed/${v.userId}/200`} className="w-12 h-12 rounded-2xl object-cover shadow-sm" alt="" />
                            <div className="flex-1">
                               <p className="font-bold text-sm">{v.userName}</p>
                               <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{new Date(v.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                            </div>
                            <div className="text-[10px] font-black text-indigo-500 bg-indigo-500/10 px-3 py-1 rounded-full uppercase">Viewed</div>
                         </div>
                      ))
                   )}
                </div>
             </div>
          </div>
        )}
      </div>

      {/* Fixed Footer - Reply Box & Viewers Icon */}
      <div className="bg-black/80 backdrop-blur-xl border-t border-white/10 z-[100] safe-bottom shrink-0">
        <div className="max-w-2xl mx-auto px-4 py-3 md:py-6">
          {/* Quick Reactions */}
          {!replyText && !isOwner && (
            <div className="flex justify-between items-center mb-4 px-2 animate-in slide-in-from-bottom-2">
              {QUICK_REACTIONS.map(emoji => (
                <button 
                  key={emoji} 
                  onClick={() => handleReply(undefined, emoji)}
                  className="text-2xl hover:scale-125 transition-transform p-1 active:scale-90"
                >
                  {emoji}
                </button>
              ))}
            </div>
          )}

          <div className="flex items-center gap-3">
            {isOwner ? (
              <div className="flex items-center justify-between w-full">
                <button 
                   onClick={toggleViewersList}
                   className="flex items-center gap-3 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-full transition-all active:scale-95 group"
                >
                  <div className="relative">
                    <svg className="w-6 h-6 text-white group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                    </svg>
                    {story.views && story.views.length > 0 && (
                      <div className="absolute -top-1 -right-1 w-3 h-3 bg-indigo-500 rounded-full border border-black animate-pulse"></div>
                    )}
                  </div>
                  <span className="text-[11px] font-black uppercase tracking-[0.2em] text-white">{story.views?.length || 0} Views</span>
                </button>
                <div className="text-[9px] font-bold text-white/40 uppercase tracking-widest mr-2">Your Story</div>
              </div>
            ) : (
              <form onSubmit={handleReply} className="flex-1 flex items-center gap-2">
                <input 
                  type="text"
                  placeholder={`Reply to ${story.userName}...`}
                  value={replyText}
                  onFocus={() => setIsPaused(true)}
                  onBlur={() => !replyText && setIsPaused(false)}
                  onChange={(e) => setReplyText(e.target.value)}
                  className="flex-1 bg-white/10 border border-white/20 rounded-full px-5 py-3 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm"
                />

                {replyText.trim() ? (
                  <button type="submit" className="text-white bg-indigo-500 p-3 rounded-full hover:bg-indigo-600 transition-all active:scale-90">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                    </svg>
                  </button>
                ) : (
                  <button 
                    type="button"
                    onClick={handleLike}
                    className={`p-2 transition-all active:scale-125 ${isLiked ? 'text-red-500' : 'text-white/70 hover:text-white'}`}
                  >
                    <svg className={`w-8 h-8 ${isLiked ? 'fill-current' : 'fill-none stroke-current'}`} strokeWidth="2" viewBox="0 0 24 24">
                      <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
                    </svg>
                  </button>
                )}
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Story, User } from '../../types';
import { likeStory, sendStoryReply, viewStory } from '../../firebase';

interface StoryViewerProps {
  stories: Story[];
  currentUser: User;
  onClose: () => void;
}

const QUICK_REACTIONS = ['😂', '❤️', '🔥', '😮', '😢', '🙌'];

export const StoryViewer: React.FC<StoryViewerProps> = ({ stories, currentUser, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [progress, setProgress] = useState(0);
  const [replyText, setReplyText] = useState('');
  const [isLiked, setIsLiked] = useState(false);
  const [showHeartAnim, setShowHeartAnim] = useState(false);
  const [showSentAnim, setShowSentAnim] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [showViewers, setShowViewers] = useState(false);

  const story = stories[currentIndex];
  // Ensure we compare UIDs as strings and handle potential undefined cases
  const isOwner = story && currentUser && String(story.userId) === String(currentUser.uid);

  useEffect(() => {
    if (!story) return;

    setIsLiked(story.likes?.includes(currentUser.uid) || false);
    setProgress(0);
    setShowViewers(false);

    // Track view if not owner
    if (!isOwner) {
      viewStory(story.id, currentUser.uid, currentUser.name);
    }

    if (isPaused) return;

    const duration = story.mediaType === 'video' ? 10000 : 5000;
    const intervalTime = 50;
    const step = (intervalTime / duration) * 100;

    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          clearInterval(timer);
          handleNext();
          return 100;
        }
        return prev + step;
      });
    }, intervalTime);

    return () => clearInterval(timer);
  }, [currentIndex, isPaused, story?.id]);

  const handleNext = () => {
    if (currentIndex < stories.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onClose();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleLike = async () => {
    if (!isLiked) {
      setShowHeartAnim(true);
      setTimeout(() => setShowHeartAnim(false), 800);
    }
    setIsLiked(!isLiked);
    await likeStory(story.id, currentUser.uid);
  };

  const triggerSentAnim = () => {
    setShowSentAnim(true);
    setTimeout(() => setShowSentAnim(false), 1500);
  };

  const handleReply = async (e?: React.FormEvent, customText?: string) => {
    e?.preventDefault();
    const text = customText || replyText.trim();
    if (!text) return;

    setReplyText('');
    setIsPaused(false);

    await sendStoryReply(story.userId, currentUser.uid, text, story);
    triggerSentAnim();

    if (customText) {
      setTimeout(handleNext, 800);
    }
  };

  const toggleViewersList = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!isOwner) return;
    setIsPaused(!showViewers);
    setShowViewers(!showViewers);
  };

  if (!story) return null;

  return (
    <div className="fixed inset-0 z-[110] bg-black flex flex-col h-full transition-all overflow-hidden touch-none">
      {/* Top Header - Progress Bars & User Info */}
      <div className="absolute top-0 inset-x-0 z-[130] pt-8 bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex gap-1.5 px-4 mb-4">
          {stories.map((_, idx) => {
            const barWidth = idx < currentIndex ? '100%' : idx === currentIndex ? progress + '%' : '0%';
            return (
              <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-white transition-all duration-100 ease-linear"
                  style={{ width: barWidth }}
                />
              </div>
            );
          })}
        </div>

        <div className="px-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img src={story.userPhoto} className="w-11 h-11 rounded-full border-2 border-white/20 object-cover shadow-lg" alt="" />
            <div>
              <h4 className="text-white font-bold text-sm leading-none mb-1">{story.userName}</h4>
              <span className="text-white/60 text-[10px] uppercase font-black tracking-widest">
                {new Date(story.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
            {isPaused && !showViewers && (
              <div className="ml-3 px-2 py-1 bg-white/10 backdrop-blur-md rounded-lg text-[8px] text-white font-black uppercase tracking-widest animate-pulse border border-white/10">
                Paused
              </div>
            )}
          </div>
          <button onClick={onClose} className="p-2 text-white/50 hover:text-white transition-all hover:scale-110 active:scale-90">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex items-center justify-center relative bg-black">
        {/* Navigation Zones */}
        {!showViewers && (
          <>
            <div className="absolute inset-y-0 left-0 w-1/3 z-30 cursor-pointer" onClick={handlePrev} />
            <div className="absolute inset-y-0 right-0 w-1/3 z-30 cursor-pointer" onClick={handleNext} />
          </>
        )}

        {showHeartAnim && (
          <div className="absolute z-[140] animate-ping">
            <svg className="w-32 h-32 text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.5)]" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
        )}

        <div className="w-full h-full flex items-center justify-center">
          {story.mediaType === 'video' ? (
            <video 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain" 
              autoPlay 
              playsInline 
              muted={false}
              onPlay={() => !isPaused && setIsPaused(false)}
            />
          ) : (
            <img 
              src={story.mediaUrl} 
              className="max-h-full w-full object-contain select-none" 
              alt="" 
              onDoubleClick={handleLike}
            />
          )}
        </div>

        {story.caption && !replyText && !showViewers && (
          <div className="absolute bottom-10 inset-x-0 p-8 text-center bg-gradient-to-t from-black/90 via-black/40 to-transparent z-40">
            <p className="text-white text-lg font-bold drop-shadow-2xl px-4">{story.caption}</p>
          </div>
        )}
      </div>

      {/* Viewer List Bottom Sheet */}
      {showViewers && (
        <div className="absolute inset-0 z-[150] flex flex-col items-center justify-end animate-in slide-in-from-bottom duration-300">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={() => { setShowViewers(false); setIsPaused(false); }}></div>
           <div className="relative w-full max-w-xl bg-white dark:bg-slate-900 rounded-t-[3rem] h-[65%] flex flex-col overflow-hidden shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
              <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between sticky top-0 bg-white/95 dark:bg-slate-900/95 backdrop-blur-md z-10">
                 <div>
                   <h3 className="text-2xl font-black">Viewers</h3>
                   <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">{story.views?.length || 0} People saw this</p>
                 </div>
                 <button onClick={() => { setShowViewers(false); setIsPaused(false); }} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-slate-200 transition-all">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" /></svg>
                 </button>
              </div>
              <div className="flex-1 overflow-y-auto p-6 space-y-3 no-scrollbar">
                 {(!story.views || story.views.length === 0) ? (
                    <div className="flex flex-col items-center justify-center h-full text-slate-400 gap-6 opacity-60">
                       <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center">
                          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                       </div>
                       <p className="text-sm font-black uppercase tracking-[0.2em]">No viewers yet</p>
                    </div>
                 ) : (
                    story.views.slice().sort((a,b) => b.timestamp - a.timestamp).map(v => (
                       <div key={v.userId} className="flex items-center gap-4 p-5 rounded-3xl bg-slate-50 dark:bg-slate-800/40 hover:bg-indigo-50 dark:hover:bg-indigo-900/10 transition-all border border-transparent hover:border-indigo-100 dark:hover:border-indigo-900/20 group">
                          <img src={`https://picsum.photos/seed/${v.userId}/200`} className="w-14 h-14 rounded-2xl object-cover shadow-sm group-hover:scale-105 transition-transform" alt="" />
                          <div className="flex-1 min-w-0">
                             <p className="font-bold text-base truncate">{v.userName}</p>
                             <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">{new Date(v.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                          </div>
                          <div className="text-[10px] font-black text-indigo-500 bg-indigo-500/10 px-4 py-1.5 rounded-xl uppercase tracking-widest border border-indigo-500/20">Seen</div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {/* Fixed Footer - Interaction UI */}
      <div className="bg-black/80 backdrop-blur-3xl border-t border-white/10 z-[120] pb-10 pt-4 shrink-0 px-6">
        <div className="max-w-2xl mx-auto">
          {/* Quick Reactions for non-owners */}
          {!replyText && !isOwner && !showViewers && (
            <div className="flex justify-between items-center mb-5 px-1 animate-in slide-in-from-bottom-2">
              {QUICK_REACTIONS.map(emoji => (
                <button 
                  key={emoji} 
                  onClick={() => handleReply(undefined, emoji)}
                  className="text-2xl hover:scale-135 transition-all p-2 active:scale-90"
                >
                  {emoji}
                </button>
              ))}
            </div>
          )}

          <div className="flex items-center gap-4">
            {isOwner ? (
              <div className="flex items-center justify-between w-full animate-in fade-in duration-500">
                <button 
                   onClick={toggleViewersList}
                   className={`flex items-center gap-4 px-8 py-4 bg-white/10 hover:bg-white/20 rounded-[1.5rem] transition-all active:scale-95 group border border-white/10 ${showViewers ? 'bg-white/30 border-white/30 shadow-[0_0_20px_rgba(255,255,255,0.1)]' : ''}`}
                >
                  <div className="relative">
                    <svg className="w-6 h-6 text-white group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                    </svg>
                    {story.views && story.views.length > 0 && (
                      <div className="absolute -top-1 -right-1 w-3 h-3 bg-indigo-500 rounded-full border border-black animate-pulse shadow-[0_0_8px_rgba(99,102,241,0.8)]"></div>
                    )}
                  </div>
                  <span className="text-xs font-black uppercase tracking-[0.25em] text-white">
                    {showViewers ? 'Close Details' : `${story.views?.length || 0} Viewers`}
                  </span>
                </button>
                <div className="flex flex-col items-end gap-1 mr-2 opacity-60">
                   <div className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Your Story</div>
                   <div className="w-12 h-0.5 bg-indigo-500 rounded-full"></div>
                </div>
              </div>
            ) : (
              <form onSubmit={handleReply} className="flex-1 flex items-center gap-3">
                <input 
                  type="text"
                  placeholder={`Reply to ${story.userName.split(' ')[0]}...`}
                  value={replyText}
                  onFocus={() => setIsPaused(true)}
                  onBlur={() => !replyText && setIsPaused(false)}
                  onChange={(e) => setReplyText(e.target.value)}
                  className="flex-1 bg-white/10 border border-white/20 rounded-[1.5rem] px-6 py-4 text-white placeholder-white/40 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all text-sm font-medium"
                />

                {replyText.trim() ? (
                  <button type="submit" className="text-white bg-indigo-500 p-4 rounded-[1.25rem] hover:bg-indigo-600 transition-all active:scale-90 shadow-lg shadow-indigo-500/20">
