        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../../types';

interface MessageBubbleProps {
  message: Message;
  isOwn: boolean;
  isAI?: boolean;
  onReply: (msg: Message) => void;
  onForward: (msg: Message) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message, isOwn, isAI, onReply, onForward }) => {
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showMenu]);

  const formatTime = (ts: number) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message.text);
    setShowMenu(false);
  };

  const renderStatus = (isMedia?: boolean) => {
    if (!isOwn) return null;

    // Status color mapping
    const baseColor = isMedia ? 'text-white/60' : 'text-slate-400 dark:text-slate-500';
    const seenColor = isMedia ? 'text-sky-300' : 'text-sky-500';

    switch (message.status) {
      case 'sent':
        return (
          <svg className={`w-3.5 h-3.5 ${baseColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
          </svg>
        );
      case 'delivered':
        return (
          <div className="flex -space-x-2">
            <svg className={`w-3.5 h-3.5 ${baseColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
            </svg>
            <svg className={`w-3.5 h-3.5 ${baseColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
            </svg>
          </div>
        );
      case 'seen':
        return (
          <div className="flex -space-x-2">
            <svg className={`w-3.5 h-3.5 ${seenColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
            </svg>
            <svg className={`w-3.5 h-3.5 ${seenColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
            </svg>
          </div>
        );
    }
  };

  const isMediaMessage = message.type === 'image' || message.type === 'video';

  return (
    <div className={`flex w-full ${isOwn ? 'justify-end' : 'justify-start'} mb-1 px-1 group/container`}>
      <div className={`flex flex-col max-w-[85%] md:max-w-[75%] group ${isOwn ? 'items-end' : 'items-start'} relative`}>

        {/* Interaction Menu (Desktop hover / Mobile click) */}
        {showMenu && (
          <div 
            ref={menuRef}
            className={`absolute z-50 bottom-full mb-3 bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-700 p-1.5 flex flex-col min-w-[150px] animate-in zoom-in-95 duration-150 ${isOwn ? 'right-0' : 'left-0'}`}
          >
            <button onClick={() => { onReply(message); setShowMenu(false); }} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-blue-500/10 text-blue-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg></div>
              Reply
            </button>
            <button onClick={handleCopy} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-indigo-500/10 text-indigo-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1" /></svg></div>
              Copy Text
            </button>
            <button onClick={() => { onForward(message); setShowMenu(false); }} className="flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-xl text-xs font-bold transition-all">
              <div className="p-1.5 bg-green-500/10 text-green-500 rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg></div>
              Forward
            </button>
          </div>
        )}

        <div 
          onClick={() => setShowMenu(!showMenu)}
          className={`relative rounded-3xl message-shadow transition-all duration-300 cursor-pointer active:scale-[0.99] overflow-hidden ${
            isMediaMessage ? 'p-1' : 'p-3.5 px-4'
          } ${
            isOwn 
            ? 'bg-gradient-to-br from-indigo-500 to-indigo-600 text-white rounded-tr-none' 
            : isAI
              ? 'bg-gradient-to-br from-slate-800 to-slate-900 text-white rounded-tl-none border border-indigo-500/20 shadow-lg'
              : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 rounded-tl-none border border-slate-200/50 dark:border-slate-700/50'
          }`}
        >
          {message.isForwarded && (
            <div className={`flex items-center gap-1.5 mb-1 opacity-60 text-[10px] font-bold italic ${isMediaMessage ? 'px-3 pt-2' : ''}`}>
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
              Forwarded
            </div>
          )}

          {isAI && !message.isForwarded && (
            <div className={`flex items-center gap-2 mb-2 ${isMediaMessage ? 'px-3 pt-2' : ''}`}>
              <div className="w-5 h-5 bg-indigo-500 rounded-lg flex items-center justify-center">
                <svg className="w-3.5 h-3.5 text-white" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" />
                </svg>
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">AI Genius</span>
            </div>
          )}

          {/* Reply Context */}
          {message.replyContext && (
            <div className={`mb-2.5 p-3 rounded-2xl text-xs border-l-4 ${isOwn ? 'bg-indigo-800/40 border-indigo-300' : 'bg-slate-100 dark:bg-slate-700/50 border-indigo-500 shadow-inner'}`}>
              <div className="font-black text-indigo-500 dark:text-indigo-400 mb-1 flex items-center gap-2">
                 <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
                 {message.replyContext.senderName}
              </div>
              <p className="opacity-70 line-clamp-1 italic font-medium">{message.replyContext.text}</p>
            </div>
          )}

          {/* Media Content */}
          {message.type === 'image' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-2xl">
              <img src={message.fileUrl} alt="Sent" className="w-full max-h-96 object-cover hover:scale-105 transition-transform duration-500" />
              <div className={`absolute bottom-3 right-3 px-2 py-1 bg-black/40 backdrop-blur-md rounded-full flex items-center gap-2 border border-white/10 opacity-0 group-hover/container:opacity-100 transition-opacity duration-300`}>
                <span className="text-[9px] font-black text-white">{formatTime(message.timestamp)}</span>
                {renderStatus(true)}
              </div>
            </div>
          )}

          {message.type === 'video' && message.fileUrl && (
            <div className="relative overflow-hidden rounded-2xl bg-black">
              <video src={message.fileUrl} className="w-full max-h-96 object-contain" controls />
              <div className={`absolute bottom-3 right-3 px-2 py-1 bg-black/40 backdrop-blur-md rounded-full flex items-center gap-2 border border-white/10 z-10 opacity-0 group-hover/container:opacity-100 transition-opacity duration-300`}>
                <span className="text-[9px] font-black text-white">{formatTime(message.timestamp)}</span>
                {renderStatus(true)}
              </div>
            </div>
          )}

          {message.type === 'file' && (
            <div className={`mb-1 p-3 rounded-2xl flex items-center gap-3.5 border ${isOwn ? 'bg-white/10 border-white/10' : 'bg-slate-50 dark:bg-slate-700/30 border-slate-100 dark:border-slate-600/50 shadow-sm'}`}>
                <div className="w-11 h-11 rounded-xl bg-indigo-500/10 dark:bg-indigo-500/20 flex items-center justify-center text-indigo-500 shrink-0">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold truncate">{message.fileName || 'Document'}</p>
                    <p className="text-[9px] font-black uppercase tracking-widest opacity-60">File Transfer</p>
                </div>
                <a href={message.fileUrl} download className="p-2.5 rounded-xl hover:bg-black/5 dark:hover:bg-white/5 transition-all">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
            </div>
          )}

          {message.type === 'text' && (
            <div className="flex flex-col">
              <p className="text-[15px] leading-[1.6] font-medium whitespace-pre-wrap">{message.text}</p>

              <div className={`flex items-center gap-2 mt-1 self-end transition-opacity duration-300 opacity-0 group-hover/container:opacity-100`}>
                <span className={`text-[9px] font-bold uppercase tracking-wider ${isOwn ? 'text-white/60' : 'text-slate-400 dark:text-slate-500'}`}>
                  {formatTime(message.timestamp)}
                </span>
                {renderStatus()}
              </div>
            </div>
          )}

          {/* Simple status always visible if it's sent but not seen for own non-text messages */}
          {!isMediaMessage && message.type !== 'text' && (
            <div className="flex items-center gap-2 mt-1 justify-end opacity-0 group-hover/container:opacity-100 transition-opacity">
              <span className={`text-[9px] font-bold uppercase tracking-wider ${isOwn ? 'text-white/60' : 'text-slate-400 dark:text-slate-500'}`}>
                {formatTime(message.timestamp)}
              </span>
              {renderStatus()}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Message } from '../../types';
import { blockUser, unblockUser, auth, getMessages } from '../../firebase';

interface PublicProfileProps {
  user: User;
  onClose: () => void;
  onCallStart?: (user: User, type: 'voice' | 'video') => void;
}

export const PublicProfile: React.FC<PublicProfileProps> = ({ user, onClose, onCallStart }) => {
  const currentUser = auth.currentUser;
  const [isBlocked, setIsBlocked] = useState(currentUser?.blockedUsers?.includes(user.uid) || false);
  const [loading, setLoading] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [mediaCount, setMediaCount] = useState(0);

  useEffect(() => {
    // Mock media count by checking messages for this user
    const fetchMediaCount = async () => {
      const chatId = [currentUser.uid, user.uid].sort().join('_');
      const msgs = await getMessages(chatId);
      const media = msgs.filter((m: Message) => m.type === 'image' || m.type === 'video');
      setMediaCount(media.length);
    };
    fetchMediaCount();
  }, [user.uid, currentUser.uid]);

  const handleToggleBlock = async () => {
    if (!currentUser) return;
    setLoading(true);
    try {
      if (isBlocked) {
        await unblockUser(currentUser.uid, user.uid);
        setIsBlocked(false);
      } else {
        if (window.confirm(`Are you sure you want to block ${user.name}?`)) {
          await blockUser(currentUser.uid, user.uid);
          setIsBlocked(true);
        }
      }
    } catch (err) {
      alert("Failed to update block status.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex justify-end">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm lg:backdrop-blur-0 lg:bg-transparent" onClick={onClose}></div>

      {/* Main Panel */}
      <div className="relative w-full lg:max-w-md h-full bg-slate-50 dark:bg-slate-950 shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        {/* Header (Sticky-ish) */}
        <div className="h-16 flex items-center px-6 gap-6 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 shrink-0">
          <button onClick={onClose} className="p-2 -ml-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-all text-slate-600 dark:text-slate-400">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <h2 className="text-lg font-bold">Contact Info</h2>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar">
          {/* Hero Section */}
          <div className="bg-white dark:bg-slate-900 px-6 py-10 flex flex-col items-center border-b border-slate-200 dark:border-slate-800 shadow-sm">
            <div className="relative group mb-6">
              <img 
                src={user.photoURL} 
                className="w-48 h-48 rounded-full object-cover shadow-xl ring-4 ring-indigo-500/10 cursor-zoom-in transition-transform hover:scale-105" 
                alt={user.name} 
              />
              <div className={`absolute bottom-3 right-3 w-6 h-6 rounded-full border-4 border-white dark:border-slate-900 ${user.status === 'online' ? 'bg-green-500' : 'bg-slate-400'}`}></div>
            </div>

            <h3 className="text-2xl font-black text-slate-900 dark:text-white text-center mb-1">{user.name}</h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-8">{user.email}</p>

            <div className="flex items-center gap-6">
               <button 
                  onClick={() => onCallStart?.(user, 'voice')}
                  className="flex flex-col items-center gap-2 group"
                >
                  <div className="w-12 h-12 rounded-2xl bg-indigo-50 dark:bg-indigo-900/20 flex items-center justify-center text-indigo-500 group-hover:bg-indigo-500 group-hover:text-white transition-all shadow-sm">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
