            </div>
          </div>
        );

      case 'chats':
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
            <SettingsItem title="Wallpaper" subtitle="Choose chat background" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>} onClick={() => setViewMode('wallpaper')} />
            <SettingsItem title="Font Size" subtitle={settings.fontSize} onClick={() => {
              const sizes = ['small', 'medium', 'large'];
              setSettings({...settings, fontSize: sizes[(sizes.indexOf(settings.fontSize) + 1) % sizes.length]});
            }} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5L6 9H2v6h4l5 4V5zM15.54 8.46a5 5 0 010 7.07" /></svg>} />
          </div>
        );

      case 'wallpaper':
        return (
          <div className="grid grid-cols-2 gap-4 p-2 animate-in slide-in-from-right-4 duration-500">
            {WALLPAPER_OPTIONS.map(wp => (
              <button 
                key={wp.id} 
                onClick={() => setSettings({...settings, wallpaper: wp.id})}
                className={`relative aspect-[9/16] rounded-2xl overflow-hidden border-4 transition-all ${settings.wallpaper === wp.id ? 'border-indigo-500 scale-[1.02]' : 'border-transparent hover:border-slate-200'}`}
              >
                <div className={`w-full h-full ${wp.class}`}>
                   {/* Mini Doodle Mock */}
                   <div className="absolute inset-0 opacity-10" style={{ backgroundImage: `url('https://www.transparenttextures.com/patterns/asfalt-dark.png')` }}></div>
                </div>
                <div className="absolute bottom-0 inset-x-0 p-3 bg-black/40 backdrop-blur-md">
                   <p className="text-[10px] font-black text-white uppercase tracking-widest">{wp.name}</p>
                </div>
                {settings.wallpaper === wp.id && (
                  <div className="absolute top-2 right-2 bg-indigo-500 text-white rounded-full p-1">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
                  </div>
                )}
              </button>
            ))}
          </div>
        );

      case 'privacy':
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
             <SettingsItem title="Last Seen" subtitle={settings.lastSeen} onClick={() => {
                const opts = ['everyone', 'contacts', 'nobody'];
                setSettings({...settings, lastSeen: opts[(opts.indexOf(settings.lastSeen) + 1) % opts.length]});
             }} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
             <SettingsItem title="Read Receipts" toggle={settings.readReceipts} onClick={() => setSettings({...settings, readReceipts: !settings.readReceipts})} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>} />
          </div>
