      case 'notifications':
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
            <SettingsItem title="Enable Notifications" toggle={settings.notificationsEnabled} onClick={() => setSettings({...settings, notificationsEnabled: !settings.notificationsEnabled})} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>} />
            <SettingsItem title="Play Sounds" toggle={settings.notificationSound} onClick={() => setSettings({...settings, notificationSound: !settings.notificationSound})} icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.536 8.464a5 5 0 010 7.072" /></svg>} />
          </div>
        );

      case 'language':
        const langs = ['English (US)', 'Hindi (India)', 'Spanish (Spain)', 'French (France)'];
        return (
          <div className="space-y-1 animate-in slide-in-from-right-4 duration-500">
             {langs.map(l => (
               <button key={l} onClick={() => setSettings({...settings, language: l})} className="w-full px-6 py-4 flex items-center justify-between hover:bg-slate-50 dark:hover:bg-slate-800/40 border-b border-slate-50 dark:border-slate-800">
                 <span className={`text-sm font-bold ${settings.language === l ? 'text-indigo-500' : 'text-slate-700 dark:text-slate-300'}`}>{l}</span>
                 {settings.language === l && <svg className="w-5 h-5 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>}
               </button>
             ))}
          </div>
        );

      case 'main':
      default:
        return (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex flex-col items-center text-center">
              <div className="relative mb-6">
                <img src={user.photoURL} className="w-28 h-28 rounded-[2.5rem] object-cover shadow-2xl ring-4 ring-indigo-500/10" alt="" />
                <div className="absolute bottom-1 right-1 w-7 h-7 bg-green-500 rounded-full border-4 border-white dark:border-slate-900 shadow-md"></div>
              </div>
              <h3 className="text-2xl font-black tracking-tight">{user.name}</h3>
              <p className="text-sm text-slate-500 mt-2 font-medium">{user.bio || 'Available'}</p>
              <div className="flex items-center gap-3 mt-6">
                <button onClick={() => setViewMode('edit')} className="flex items-center gap-2 bg-indigo-500/10 text-indigo-500 px-8 py-3 rounded-full hover:bg-indigo-500 hover:text-white transition-all font-bold text-[10px] uppercase tracking-widest">Edit Profile</button>
                <button onClick={() => setViewMode('settings')} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full hover:bg-indigo-500 hover:text-white transition-all text-slate-500"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
              </div>
            </div>
            <div className="space-y-3 pt-4">
              <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 ml-2">Quick Access</h4>
