  const panelContent = (
    <div className={`flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in duration-300`}>
      {renderHeader()}
      <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar pb-24">
