          <div className="relative cursor-pointer" onClick={() => onUserClick(isGroup ? ({} as User) : otherUser!)}>
            <img src={isGroup ? (chat.groupIcon || `https://picsum.photos/seed/${chat.id}/200`) : otherUser?.photoURL} className="w-10 h-10 rounded-full object-cover border border-slate-200 dark:border-slate-700" alt="" />
            {!isGroup && otherUser?.status === 'online' && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white dark:border-slate-900"></div>}
          </div>
          <div className="min-w-0 cursor-pointer" onClick={() => onUserClick(isGroup ? ({} as User) : otherUser!)}>
