  if (isTabMode) return panelContent;
  return (
    <div className={`fixed inset-0 z-50 flex justify-end`}>
      <div className={`absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity`} onClick={onClose}></div>
