export const admin_toggleAdminAccess = async (uid: string) => {
  const users = getLocal(STORAGE_KEY_USERS);
  const i = users.findIndex((u: any) => u.uid === uid);
  if (i !== -1) {
    // Prevent self-demotion or demoting the super admin via standard panel
