import { GoogleGenAI } from "@google/genai";

let aiClient: GoogleGenAI | null = null;

const getClient = () => {
  if (!aiClient) {
    // We check for process safety to prevent browser crashes if polyfills are missing
    const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : '';
    if (!apiKey) {
      console.warn("Gemini API Key is missing.");
    }
    aiClient = new GoogleGenAI({ apiKey: apiKey || 'dummy_key_to_prevent_crash' });
  }
  return aiClient;
};

export const getAIResponse = async (prompt: string) => {
  try {
    const ai = getClient();
    // Correct method: use ai.models.generateContent with both model and prompt.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a helpful and witty chat assistant. Keep responses brief and conversational, suitable for a mobile chat app. If asked about facts, use common knowledge or admit if unsure.",
      }
    });
    // Access the text property directly (not a method).
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Sorry, I'm having a bit of trouble connecting to my brain right now. 🤖";
  }
};

import React, { useState, useEffect } from 'react';
import { AuthView } from './components/Auth/AuthView';
import { ChatDashboard } from './components/Chat/ChatDashboard';
import { AdminDashboard } from './components/Admin/AdminDashboard';
import { useAuth } from './hooks/useAuth';

type AppView = 'auth' | 'role_select' | 'user' | 'admin';

const App: React.FC = () => {
  const { user, loading } = useAuth();
  const [view, setView] = useState<AppView>('auth');
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem('theme') === 'dark' || 
           (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // Handle initial view routing and transitions
  useEffect(() => {
    if (!user) {
      setView('auth');
    } else if (user.isAdmin) {
      // For admins, default to role selection unless they've already chosen a path
      if (view === 'auth') {
        setView('role_select');
      }
    } else {
      setView('user');
    }
  }, [user, view]);

  if (loading) {
    return (
      <div className="h-[100dvh] w-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-slate-500 animate-pulse font-medium text-sm">Initializing Secure Session...</p>
        </div>
      </div>
    );
  }

  // Guard: If no user, always show Auth
  if (!user) {
    return <AuthView />;
