    });
  } else {
    if (userSnap.data().isGloballyBlocked) {
      await firebaseSignOut(auth);
      throw new Error("This account has been suspended.");
    }
    await updateDoc(userRef, { status: 'online', lastSeen: Date.now() });
  }
