  const groupId = 'group_' + crypto.randomUUID();
  const newGroup = {
    id: groupId,
    type: 'group',
    name,
    participants: [...participants, adminId],
    adminIds: [adminId],
    updatedAt: Date.now(),
    lockedBy: []
  };
  await setDoc(doc(db, "chats", groupId), newGroup);
  return newGroup;
};

