  if (snap.exists()) {
    const views = snap.data().views || [];
    if (!views.some((v: any) => v.userId === userId)) {
      await updateDoc(storyRef, {
        views: arrayUnion({ userId, userName, timestamp: Date.now() })
      });
    }
  }
