  if (snap.exists()) {
    const likes = snap.data().likes || [];
    if (likes.includes(userId)) {
      await updateDoc(storyRef, { likes: arrayRemove(userId) });
    } else {
      await updateDoc(storyRef, { likes: arrayUnion(userId) });
    }
  }
