export const updateProfile = async (user: any, updates: any) => {
  const uid = user.uid || user.id;
  if (auth.currentUser) {
    await firebaseUpdateProfile(auth.currentUser, {
      displayName: updates.name || user.name,
      photoURL: updates.photoURL || user.photoURL
    });
